(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-951":{scenario:{company:"Huong Dong Beverages",supervisor:{name:"Khúc Đình Viễn",role:{vi:"Trưởng phòng Nghiên cứu & Phát triển sản phẩm",en:"Head of Product R&D"}},ref_code:"NPD-4418",title:{vi:"Đúng nhóm thực phẩm. Đủ giá trị tiệt trùng. An toàn từng lon.",en:"Right food class. Enough lethality. Safe in every can."},brief:{vi:"Bạn rà soát hồ sơ quy trình NPD-4418 cho sữa bắp đóng lon 240 mL (pH 6.5, aw 0.98). Mẻ thử được giữ nhiệt 10 phút; cảm biến buồng nồi hấp ghi 121°C, đầu dò điểm lạnh trong lon ghi 118°C suốt thời gian giữ. Tiêu chuẩn nội bộ yêu cầu F0 ≥ 6 phút. Dùng terminal đọc nhật ký, sửa nhóm axit của sản phẩm và giá trị F0 đạt được, rồi lập báo cáo có căn cứ.",en:"You are reviewing process file NPD-4418 for a 240 mL canned corn milk drink (pH 6.5, aw 0.98). The trial batch was held for 10 minutes; the retort chamber sensor read 121°C while the cold-spot probe inside the can read 118°C throughout the hold. The internal specification requires F0 ≥ 6 minutes. Use the terminal to read the logs, correct the product acid class and the achieved F0, then write an evidence-based report."},reference_title:{vi:"Phiếu đặc tính sản phẩm & báo cáo thâm nhập nhiệt đã duyệt · NPD-4418",en:"Approved product profile & heat penetration report · NPD-4418"},fields:[{id:"ACID_CLASS",label:{vi:"Nhóm axit của sản phẩm",en:"Product acid class"},initial:"ACID",expected:"LOW-ACID",choices:["ACID","ACIDIFIED","LOW-ACID"],reference:"Phiếu đặc tính sản phẩm (pH, aw)",hint:{vi:"pH lớn hơn 4.6 và aw lớn hơn 0.85 là thực phẩm ít axit, phải tiệt trùng thương mại bằng nồi hấp áp lực.",en:"pH above 4.6 and aw above 0.85 means a low-acid food that needs commercial sterilisation in a pressure retort."}},{id:"F0_VALUE",label:{vi:"Giá trị F0 đạt được (phút)",en:"Achieved F0 (minutes)"},initial:"9.77",expected:"4.9",reference:"Báo cáo thâm nhập nhiệt tại điểm lạnh",ref_value:{vi:"Điểm lạnh 118°C trong 10 phút giữ; L(118°C) = 0.490; L(121°C) = 0.977",en:"Cold spot 118°C for the 10-minute hold; L(118°C) = 0.490; L(121°C) = 0.977"},hint:{vi:"F0 tính theo nhiệt độ tại điểm lạnh nhất của sản phẩm, không theo nhiệt độ buồng nồi hấp.",en:"F0 is based on the product cold-spot temperature, not the retort chamber temperature."}}],sop32:{vi:"F0 (phút) = hệ số gây chết L tại nhiệt độ điểm lạnh x thời gian giữ nhiệt; bỏ qua pha nâng và hạ nhiệt (an toàn); bảng L: 115°C 0.245, 118°C 0.490, 121°C 0.977.",en:"F0 (minutes) = lethal rate L at the cold-spot temperature x hold time; ignore come-up and cooling (conservative); L table: 115°C 0.245, 118°C 0.490, 121°C 0.977."},context:{label:"RETORT LOG / NPD-4418",metrics:[{label:{vi:"Nhiệt độ buồng",en:"Chamber temperature"},value:"121°C"},{label:{vi:"Nhiệt độ điểm lạnh",en:"Cold-spot temperature"},value:"118°C"},{label:{vi:"Thời gian giữ nhiệt",en:"Hold time"},value:"10 min"},{label:{vi:"F0 yêu cầu",en:"Required F0"},value:"≥ 6 min"}]},crisis:{vi:"Quản đốc sản xuất nhắn: “Buồng nồi đạt 121°C rồi, cứ ghi F0 9.77 và nhóm ACID cho đỡ phải chạy lại. Mẻ thử này phải gửi khách hàng nếm thử sáng mai.”",en:"The production supervisor messages you: “The chamber reached 121°C, just record F0 9.77 and class ACID so we don't have to rerun. This trial batch must go to the customer for tasting tomorrow morning.”"},options:{safe:{vi:"Cách ly mẻ thử T-07, không gửi khách; báo trưởng phòng R&D và QA; đề xuất kéo dài thời gian giữ nhiệt (tối thiểu 13 phút ở 118°C điểm lạnh) và thẩm định lại bằng thử thâm nhập nhiệt.",en:"Quarantine trial batch T-07 and do not send it; inform the R&D head and QA; propose a longer hold (at least 13 minutes at a 118°C cold spot) and revalidate with a heat penetration test."},shortcut:{vi:"Ghi F0 9.77 theo nhiệt độ buồng và nhóm ACID, gửi mẻ thử cho khách rồi điều chỉnh quy trình sau.",en:"Record F0 9.77 from the chamber temperature and class ACID, ship the trial batch and fix the process later."},wait:{vi:"Không ký hồ sơ và chờ quản đốc tự quyết định có gửi mẫu hay không.",en:"Leave the file unsigned and let the supervisor decide whether to send the samples."}},questions:{vi:["Vì sao sản phẩm thuộc nhóm LOW-ACID và F0 chỉ đạt 4.9 phút? Nhật ký nào trong terminal chứng minh?","Bạn xử lý mẻ thử T-07 và sửa quy trình thế nào để đạt F0 ≥ 6 phút mà vẫn kiểm soát rủi ro Clostridium botulinum?"],en:["Why is the product LOW-ACID and why does F0 reach only 4.9 minutes? Which terminal logs prove it?","How do you handle trial batch T-07 and revise the process to reach F0 ≥ 6 minutes while controlling the Clostridium botulinum risk?"]},hints:{vi:["Chạy cat spec.txt và so pH, aw với ngưỡng phân loại thực phẩm ít axit.","So sánh chamber.log với coldspot.log, rồi nhân hệ số L đúng nhiệt độ với thời gian giữ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: sản phẩm chưa đạt giá trị tiệt trùng phải được cách ly, không xuất xưởng."],en:["Run cat spec.txt and compare pH and aw with the low-acid thresholds.","Compare chamber.log with coldspot.log, then multiply the correct L value by the hold time as in SOP 3.2.","Re-read SOP 4.2: product below the required lethality must be quarantined, never released."]},terminal:{system:"retort-scada",settable:["ACID_CLASS","F0_VALUE"],commands:[{cmd:"status",out:{vi:"Nồi hấp R2 · mẻ thử T-07 · sữa bắp lon 240 mL · chu trình đã kết thúc, chờ phê duyệt xuất mẫu",en:"Retort R2 · trial batch T-07 · corn milk 240 mL can · cycle complete, awaiting release approval"}},{cmd:"cat spec.txt",out:{vi:"Đặc tính sản phẩm: pH 6.5 · aw 0.98 · lon kim loại ghép kín · bảo quản ở nhiệt độ thường",en:"Product profile: pH 6.5 · aw 0.98 · hermetically sealed metal can · ambient storage"}},{cmd:"cat chamber.log",out:{vi:"Buồng nồi hấp: giữ 121.0°C trong 10 phút · áp suất ổn định · không có cảnh báo",en:"Retort chamber: held at 121.0°C for 10 minutes · stable pressure · no alarms"}},{cmd:"cat coldspot.log",out:{vi:"Đầu dò điểm lạnh lon số 3: 118.0°C suốt 10 phút giữ nhiệt · chậm hơn buồng 3°C",en:"Cold-spot probe in can 3: 118.0°C throughout the 10-minute hold · 3°C below the chamber"}},{cmd:"cat lethality.txt",out:{vi:"Bảng hệ số gây chết (Tref 121.1°C, z 10°C): 115°C 0.245 · 118°C 0.490 · 121°C 0.977",en:"Lethal rate table (Tref 121.1°C, z 10°C): 115°C 0.245 · 118°C 0.490 · 121°C 0.977"}}]}},learning:{summary:{vi:"Kỹ sư công nghệ thực phẩm và phát triển sản phẩm biến ý tưởng thành sản phẩm thương mại: xây dựng công thức, chọn nguyên liệu, thiết kế quy trình chế biến và bảo quản, thử cảm quan, xác định hạn sử dụng và chuyển giao sang sản xuất quy mô lớn. Nghề đòi hỏi nền tảng hóa sinh, vi sinh, kỹ thuật nhiệt và luôn đặt an toàn thực phẩm lên trước chi phí và tiến độ.",en:"A food technologist and product developer turns ideas into commercial products: formulating recipes, choosing ingredients, designing processing and preservation steps, running sensory tests, setting shelf life and scaling up to full production. The role requires biochemistry, microbiology and thermal processing knowledge and always puts food safety ahead of cost and deadlines."},responsibilities:{vi:["Nghiên cứu nhu cầu, xây dựng và tối ưu công thức sản phẩm mới theo chi phí mục tiêu.","Thiết kế quy trình chế biến, chế độ thanh trùng hoặc tiệt trùng và thông số kiểm soát.","Tổ chức thử cảm quan, phân tích lý hóa, vi sinh và nghiên cứu hạn sử dụng.","Chuyển giao từ phòng thí nghiệm sang sản xuất thử và sản xuất hàng loạt.","Lập hồ sơ kỹ thuật, thông tin nhãn và hồ sơ tự công bố sản phẩm theo quy định."],en:["Research needs and develop and optimise new product formulas against a target cost.","Design processing steps, pasteurisation or sterilisation regimes and control parameters.","Run sensory, physicochemical, microbiological and shelf-life studies.","Scale up from the laboratory to pilot runs and full production.","Prepare technical files, label information and product self-declaration dossiers."]},competencies:[{name:{vi:"Xây dựng công thức",en:"Formulation"},desc:{vi:"Cân bằng hương vị, cấu trúc, dinh dưỡng, độ ổn định và chi phí nguyên liệu.",en:"Balance taste, texture, nutrition, stability and ingredient cost."}},{name:{vi:"Kỹ thuật xử lý nhiệt",en:"Thermal processing"},desc:{vi:"Tính F0, giá trị thanh trùng và thẩm định chế độ nhiệt bằng thử thâm nhập nhiệt.",en:"Calculate F0 and pasteurisation values and validate regimes with heat penetration tests."}},{name:{vi:"Cảm quan & hạn sử dụng",en:"Sensory & shelf life"},desc:{vi:"Thiết kế phép thử cảm quan và nghiên cứu hạn dùng thực tế hoặc gia tốc.",en:"Design sensory tests and real-time or accelerated shelf-life studies."}},{name:{vi:"Chuyển giao sản xuất",en:"Scale-up"},desc:{vi:"Chuyển công thức từ mẻ nhỏ sang dây chuyền, xử lý chênh lệch thiết bị và nguyên liệu.",en:"Move recipes from bench batches to the line and resolve equipment and ingredient differences."}},{name:{vi:"An toàn ngay từ thiết kế",en:"Safety by design"},desc:{vi:"Phân tích mối nguy từ giai đoạn ý tưởng và từ chối phát hành sản phẩm chưa được thẩm định.",en:"Analyse hazards from the concept stage and refuse to release unvalidated products."}}],knowledge:{vi:["Luật An toàn thực phẩm số 55/2010/QH12 và Nghị định 15/2018/NĐ-CP về tự công bố sản phẩm.","Nghị định 43/2017/NĐ-CP về nhãn hàng hóa, sửa đổi bởi Nghị định 111/2021/NĐ-CP.","Quy phạm thực hành vệ sinh Codex cho thực phẩm đóng hộp ít axit và axit hóa (CXC 23-1979).","Động học tiêu diệt vi sinh vật: giá trị D, z, F0 và mức tiệt trùng 12D đối với Clostridium botulinum.","Hoạt độ nước, pH và công nghệ rào cản (hurdle technology) trong bảo quản thực phẩm."],en:["Food Safety Law No. 55/2010/QH12 and Decree 15/2018/ND-CP on product self-declaration.","Decree 43/2017/ND-CP on goods labelling, amended by Decree 111/2021/ND-CP.","Codex code of hygienic practice for low-acid and acidified low-acid canned foods (CXC 23-1979).","Microbial inactivation kinetics: D, z and F0 values and the 12D botulinum cook.","Water activity, pH and hurdle technology in food preservation."]},tools:["Máy đo pH & hoạt độ nước (aw)","Nồi hấp tiệt trùng thử nghiệm","Bộ ghi nhiệt thâm nhập (thermocouple)","Khúc xạ kế đo độ Brix","Phần mềm tính dinh dưỡng & chi phí công thức"],kpis:{vi:["Tỷ lệ sản phẩm mới ra thị trường đúng tiến độ.","Chi phí nguyên liệu trên đơn vị so với mục tiêu.","Số sự cố chất lượng, an toàn sau khi chuyển giao sản xuất (mục tiêu bằng 0).","Điểm chấp nhận cảm quan của nhóm người tiêu dùng mục tiêu."],en:["Share of new products launched on schedule.","Ingredient cost per unit versus target.","Quality or safety incidents after scale-up (target zero).","Sensory acceptance score from the target consumer panel."]},day:[{time:"08:00",vi:"Họp dự án sản phẩm mới, cập nhật phản hồi của khách hàng thử.",en:"New product project meeting and review of customer trial feedback."},{time:"09:30",vi:"Pha chế mẫu công thức, đo Brix, pH, độ nhớt và ghi biên bản thí nghiệm.",en:"Make formula samples, measure Brix, pH and viscosity and log the trial."},{time:"11:00",vi:"Chạy thử nồi hấp, gắn đầu dò điểm lạnh vào lon mẫu.",en:"Run a trial retort cycle with cold-spot probes in sample cans."},{time:"14:00",vi:"Tổ chức đánh giá cảm quan với hội đồng nội bộ.",en:"Run a sensory evaluation with the internal panel."},{time:"16:00",vi:"Tính F0, chi phí công thức và cập nhật hồ sơ kỹ thuật sản phẩm.",en:"Calculate F0 and formula cost and update the technical file."}],mistakes:{vi:["Tính giá trị tiệt trùng theo nhiệt độ buồng nồi hấp thay vì điểm lạnh của sản phẩm.","Xếp sai nhóm axit, chỉ thanh trùng cho thực phẩm ít axit cần tiệt trùng.","Đổi nguyên liệu, độ nhớt hoặc cỡ bao bì mà không thẩm định lại chế độ nhiệt."],en:["Calculating lethality from the retort chamber instead of the product cold spot.","Misclassifying acidity and only pasteurising a low-acid food that needs sterilisation.","Changing ingredients, viscosity or pack size without revalidating the thermal process."]},career:[{vi:"Kỹ thuật viên phòng thí nghiệm R&D",en:"R&D laboratory technician"},{vi:"Kỹ sư phát triển sản phẩm",en:"Product development engineer"},{vi:"Trưởng nhóm phát triển sản phẩm",en:"Product development team lead"},{vi:"Giám đốc nghiên cứu & phát triển",en:"Research & development director"}],glossary:[{term:"F0",vi:"Thời gian tương đương (phút) ở 121.1°C với z 10°C mà quá trình nhiệt đạt được.",en:"Equivalent minutes at 121.1°C with z 10°C delivered by a thermal process."},{term:"D value",vi:"Thời gian ở một nhiệt độ để giảm 90% (một bậc logarit) quần thể vi sinh vật.",en:"Time at a given temperature to reduce a microbial population by 90% (one log)."},{term:"Low-acid food",vi:"Thực phẩm ít axit: pH lớn hơn 4.6 và aw lớn hơn 0.85, cần tiệt trùng thương mại.",en:"Food with pH above 4.6 and aw above 0.85 that needs commercial sterilisation."},{term:"Water activity (aw)",vi:"Hoạt độ nước: lượng nước tự do vi sinh vật có thể sử dụng, từ 0 đến 1.",en:"Free water available to microorganisms, on a scale from 0 to 1."},{term:"Cold spot",vi:"Điểm lạnh: vị trí trong bao bì nóng lên chậm nhất, dùng để tính giá trị tiệt trùng.",en:"The slowest-heating point in the pack, used to calculate lethality."}],quiz:[{q:{vi:"Thực phẩm đóng hộp nào sau đây là thực phẩm ít axit cần tiệt trùng bằng nồi hấp?",en:"Which canned food below is a low-acid food requiring retort sterilisation?"},options:{vi:["Nước cam pH 3.6","Dưa chuột ngâm giấm pH 4.0","Sữa bắp pH 6.5, aw 0.98","Mứt dâu aw 0.80"],en:["Orange juice pH 3.6","Pickled cucumber pH 4.0","Corn milk pH 6.5, aw 0.98","Strawberry jam aw 0.80"]},answer:2,explain:{vi:"Sữa bắp có pH lớn hơn 4.6 và aw lớn hơn 0.85 nên là thực phẩm ít axit, bào tử Clostridium botulinum có thể phát triển.",en:"Corn milk has pH above 4.6 and aw above 0.85, so it is low-acid and Clostridium botulinum spores can grow."}},{q:{vi:"Điểm lạnh giữ 118°C (L = 0.490) trong 20 phút. F0 đạt được là bao nhiêu?",en:"The cold spot is held at 118°C (L = 0.490) for 20 minutes. What F0 is achieved?"},options:{vi:["9.8 phút","20 phút","19.5 phút","4.9 phút"],en:["9.8 min","20 min","19.5 min","4.9 min"]},answer:0,explain:{vi:"F0 = L x thời gian = 0.490 x 20 = 9.8 phút.",en:"F0 = L x time = 0.490 x 20 = 9.8 minutes."}},{q:{vi:"Mẻ sản phẩm chưa đạt F0 yêu cầu nhưng khách hàng đang chờ mẫu. Bạn làm gì?",en:"A batch has not reached the required F0 but the customer is waiting for samples. What do you do?"},options:{vi:["Gửi mẫu kèm ghi chú","Cách ly mẻ, báo QA và chạy lại theo quy trình đã thẩm định","Sửa F0 trên hồ sơ cho đạt","Chờ quản đốc quyết định"],en:["Send samples with a note","Quarantine the batch, inform QA and rerun a validated process","Edit F0 in the file to pass","Wait for the supervisor to decide"]},answer:1,explain:{vi:"Sản phẩm thiếu giá trị tiệt trùng có nguy cơ ngộ độc botulinum; phải cách ly và chạy lại theo quy trình đã thẩm định.",en:"Under-processed product carries a botulism risk; it must be quarantined and reprocessed under a validated regime."}},{q:{vi:"Mức tiệt trùng 12D đối với Clostridium botulinum nghĩa là gì?",en:"What does a 12D process for Clostridium botulinum mean?"},options:{vi:["Giữ nhiệt 12 phút","Bảo quản 12 ngày","Nhiệt độ cao hơn chuẩn 12°C","Giảm 12 bậc logarit quần thể bào tử"],en:["Hold for 12 minutes","Store for 12 days","Run 12°C above reference","Reduce the spore population by 12 logs"]},answer:3,explain:{vi:"12D là thời gian bằng 12 lần giá trị D, giảm quần thể bào tử 10 mũ 12 lần, tương ứng F0 tối thiểu khoảng 3 phút.",en:"12D equals 12 times the D value, a 10 to the 12th reduction in spores, equivalent to a minimum F0 of about 3 minutes."}}]}},"KK-952":{scenario:{company:"Dong Xanh Meat Products",supervisor:{name:"Vũ Thị Hằng",role:{vi:"Trưởng nhóm HACCP",en:"HACCP Team Leader"}},ref_code:"DEV-0517",title:{vi:"Đúng điểm tới hạn. Đủ lô nghi ngờ. Không xuất hàng chưa an toàn.",en:"Right CCP. Full suspect lot. No unsafe shipments."},brief:{vi:"Bạn hoàn thiện biên bản sai lệch DEV-0517 tại công đoạn nấu xúc xích gà. Đây là bước duy nhất tiêu diệt Salmonella và Listeria, có giới hạn tới hạn nhiệt độ tâm ≥ 72°C, giám sát 30 phút một lần. Lần đo 09:30 đạt 75°C, lần đo 10:00 chỉ 68°C, dây chuyền dừng lúc 10:15; công suất 1600 gói/giờ. Sửa phân loại biện pháp kiểm soát và số gói phải giữ lại, rồi lập báo cáo có căn cứ.",en:"You are completing deviation record DEV-0517 at the chicken sausage cooking step. This is the only step that kills Salmonella and Listeria, with a critical limit of core temperature ≥ 72°C monitored every 30 minutes. The 09:30 check read 75°C, the 10:00 check only 68°C, and the line stopped at 10:15; output is 1600 packs per hour. Correct the control category and the number of packs on hold, then write an evidence-based report."},reference_title:{vi:"Kế hoạch HACCP & nhật ký giám sát CCP đã duyệt · DEV-0517",en:"Approved HACCP plan & CCP monitoring log · DEV-0517"},fields:[{id:"CTRL_CAT",label:{vi:"Phân loại biện pháp kiểm soát bước nấu",en:"Control category of the cooking step"},initial:"OPRP",expected:"CCP",choices:["PRP","OPRP","CCP"],reference:"Bảng phân tích mối nguy & cây quyết định",hint:{vi:"Bước loại bỏ mối nguy đáng kể, có giới hạn tới hạn đo được và không có bước sau kiểm soát lại là điểm kiểm soát tới hạn.",en:"A step that eliminates a significant hazard, has a measurable critical limit and no later control is a critical control point."}},{id:"HOLD_PACKS",label:{vi:"Số gói phải giữ lại (gói)",en:"Packs to place on hold"},initial:"400",expected:"1200",reference:"Nhật ký giám sát nhiệt độ tâm",ref_value:{vi:"09:30 đạt 75°C; 10:00 không đạt 68°C; dừng chuyền 10:15; 1600 gói/giờ",en:"09:30 pass 75°C; 10:00 fail 68°C; line stopped 10:15; 1600 packs/hour"},hint:{vi:"Lô nghi ngờ bắt đầu từ lần giám sát đạt gần nhất, không phải từ lúc phát hiện sai lệch.",en:"The suspect lot starts at the last passing check, not at the moment the deviation was found."}}],sop32:{vi:"Lô nghi ngờ = toàn bộ sản phẩm từ lần giám sát đạt gần nhất trước sai lệch đến lúc dừng chuyền; số gói = thời gian (giờ) x công suất (gói/giờ).",en:"Suspect lot = all product from the last passing check before the deviation until the line stopped; packs = time (hours) x output (packs/hour)."},context:{label:"BIÊN BẢN SAI LỆCH / DEV-0517",metrics:[{label:{vi:"Giới hạn tới hạn",en:"Critical limit"},value:"≥ 72°C core"},{label:{vi:"Tần suất giám sát",en:"Monitoring frequency"},value:"30 min"},{label:{vi:"Công suất chuyền",en:"Line output"},value:"1600 /h"}]},crisis:{vi:"Trưởng ca nhắn: “Chỉ giữ 400 gói sau 10:00 thôi, hàng trước đó chắc chắn chín rồi. Xe giao hàng đang chờ, giữ cả lô là trễ hợp đồng với nhà phân phối.”",en:"The shift leader messages you: “Hold only the 400 packs after 10:00, everything before that was surely cooked. The truck is waiting and holding the whole lot will breach the distributor contract.”"},options:{safe:{vi:"Giữ đủ 1200 gói, lập biên bản sai lệch, báo trưởng nhóm HACCP và giám đốc chất lượng; đề xuất lấy mẫu vi sinh, đánh giá xử lý (nấu lại đã thẩm định hoặc hủy) và báo sớm nhà phân phối.",en:"Hold all 1200 packs, log the deviation and inform the HACCP leader and quality director; propose microbial sampling, a disposition review (validated recook or destruction) and early notice to the distributor."},shortcut:{vi:"Chỉ giữ 400 gói sau 10:00, giao phần còn lại cho kịp xe rồi theo dõi khiếu nại.",en:"Hold only the 400 packs after 10:00, ship the rest on time and watch for complaints."},wait:{vi:"Để nguyên hàng trên chuyền và chờ trưởng ca tự quyết định.",en:"Leave the product on the line and let the shift leader decide."}},questions:{vi:["Vì sao bước nấu là CCP chứ không phải OPRP, và vì sao phải giữ 1200 gói? Nhật ký nào chứng minh?","Bạn đề xuất hành động khắc phục, thẩm tra và trao đổi với nhà phân phối thế nào để kiểm soát rủi ro Listeria?"],en:["Why is the cooking step a CCP rather than an OPRP, and why must 1200 packs be held? Which log proves it?","What corrective action, verification and distributor communication do you propose to control the Listeria risk?"]},hints:{vi:["Đặt bảng phân tích mối nguy cạnh biên bản và trả lời từng câu của cây quyết định cho bước nấu.","Xác định lần giám sát đạt gần nhất trước sai lệch rồi tính thời lượng đến lúc dừng chuyền theo SOP mục 3.2.","Đọc lại SOP mục 4.2: sản phẩm nghi ngờ không được xuất khi chưa có đánh giá và phê duyệt của nhóm HACCP."],en:["Place the hazard analysis next to the record and answer each decision tree question for the cooking step.","Find the last passing check before the deviation and calculate the time to the line stop as in SOP 3.2.","Re-read SOP 4.2: suspect product cannot ship before the HACCP team has assessed and approved it."]}},learning:{summary:{vi:"Chuyên viên an toàn thực phẩm xây dựng, vận hành và duy trì hệ thống HACCP, ISO 22000 tại nhà máy: phân tích mối nguy, thiết lập chương trình tiên quyết, điểm kiểm soát tới hạn, giám sát, hành động khắc phục, thẩm tra và truy xuất. Công việc đòi hỏi hiểu vi sinh, hóa học thực phẩm, quy định pháp luật và bản lĩnh nói không với hàng chưa an toàn dù chịu áp lực tiến độ.",en:"A food safety specialist builds, runs and maintains the plant's HACCP and ISO 22000 system: hazard analysis, prerequisite programmes, critical control points, monitoring, corrective action, verification and traceability. The role requires microbiology, food chemistry and regulatory knowledge and the courage to say no to unsafe product under schedule pressure."},responsibilities:{vi:["Dẫn dắt nhóm HACCP phân tích mối nguy sinh học, hóa học, vật lý và chất gây dị ứng.","Xác định PRP, OPRP, CCP và thiết lập giới hạn tới hạn, tần suất giám sát.","Xử lý sai lệch: cách ly sản phẩm, hành động khắc phục, đánh giá và quyết định xử lý.","Thẩm tra hệ thống: đánh giá nội bộ, lấy mẫu kiểm nghiệm, diễn tập truy xuất và thu hồi.","Đào tạo nhân viên, làm việc với đoàn đánh giá chứng nhận và cơ quan quản lý."],en:["Lead the HACCP team in analysing biological, chemical, physical and allergen hazards.","Define PRPs, OPRPs and CCPs and set critical limits and monitoring frequency.","Handle deviations: hold product, take corrective action, assess and decide disposition.","Verify the system: internal audits, product testing, traceability and recall drills.","Train staff and work with certification auditors and regulators."]},competencies:[{name:{vi:"Phân tích mối nguy",en:"Hazard analysis"},desc:{vi:"Đánh giá khả năng xảy ra và mức độ nghiêm trọng để xác định mối nguy đáng kể.",en:"Assess likelihood and severity to identify significant hazards."}},{name:{vi:"Thiết kế kế hoạch HACCP",en:"HACCP plan design"},desc:{vi:"Áp dụng cây quyết định, đặt giới hạn tới hạn có căn cứ khoa học và cách giám sát phù hợp.",en:"Apply the decision tree and set science-based critical limits with suitable monitoring."}},{name:{vi:"Xử lý sai lệch & thu hồi",en:"Deviation & recall handling"},desc:{vi:"Khoanh đúng lô nghi ngờ, ra quyết định xử lý và điều phối thu hồi khi cần.",en:"Define the right suspect lot, decide disposition and coordinate recalls when needed."}},{name:{vi:"Đánh giá nội bộ",en:"Internal auditing"},desc:{vi:"Thu thập bằng chứng khách quan, phát hiện điểm không phù hợp và theo dõi khắc phục.",en:"Gather objective evidence, find nonconformities and follow up corrective actions."}},{name:{vi:"Bản lĩnh tuân thủ",en:"Compliance courage"},desc:{vi:"Giữ hàng nghi ngờ dù bị áp lực giao hàng và báo cáo minh bạch lên cấp có thẩm quyền.",en:"Hold suspect product despite delivery pressure and escalate transparently."}}],knowledge:{vi:["Nguyên tắc chung về vệ sinh thực phẩm Codex CXC 1-1969 với 12 bước, 7 nguyên tắc HACCP.","ISO 22000:2018 về hệ thống quản lý an toàn thực phẩm và cách phân biệt PRP, OPRP, CCP.","ISO/TS 22002-1 về chương trình tiên quyết trong sản xuất thực phẩm.","Luật An toàn thực phẩm số 55/2010/QH12 và các văn bản hướng dẫn.","Đặc tính vi sinh vật gây bệnh: Salmonella, Listeria monocytogenes, Clostridium perfringens."],en:["Codex General Principles of Food Hygiene CXC 1-1969 with the 12 steps and 7 HACCP principles.","ISO 22000:2018 on food safety management systems and the difference between PRP, OPRP and CCP.","ISO/TS 22002-1 on prerequisite programmes for food manufacturing.","Food Safety Law No. 55/2010/QH12 and its guiding documents.","Characteristics of pathogens: Salmonella, Listeria monocytogenes and Clostridium perfringens."]},tools:["Nhiệt kế đầu dò đã hiệu chuẩn","Máy dò kim loại & mẫu thử chuẩn","Bộ test ATP vệ sinh bề mặt","Phần mềm quản lý HACCP & truy xuất","Bảng kiểm đánh giá nội bộ"],kpis:{vi:["Tỷ lệ sai lệch CCP được phát hiện và xử lý đúng hạn.","Số khiếu nại về an toàn thực phẩm (mục tiêu bằng 0).","Thời gian truy xuất một lô hàng (mục tiêu dưới 2 giờ).","Tỷ lệ điểm không phù hợp được khắc phục đúng hạn."],en:["Share of CCP deviations detected and handled on time.","Food safety complaints (target zero).","Time to trace one lot (target under 2 hours).","Share of nonconformities closed on time."]},day:[{time:"07:00",vi:"Rà soát nhật ký giám sát CCP ca đêm và ký xác nhận hồ sơ.",en:"Review night-shift CCP monitoring logs and sign off the records."},{time:"08:30",vi:"Kiểm tra vệ sinh dây chuyền trước sản xuất, test ATP bề mặt tiếp xúc.",en:"Check pre-start line hygiene and run ATP tests on contact surfaces."},{time:"10:00",vi:"Xử lý sai lệch nhiệt độ tâm, cách ly lô nghi ngờ và lập biên bản.",en:"Handle a core temperature deviation, hold the suspect lot and record it."},{time:"14:00",vi:"Họp nhóm HACCP đánh giá tác động khi đổi nhà cung cấp gia vị.",en:"HACCP team meeting on the impact of a new spice supplier."},{time:"16:00",vi:"Đào tạo công nhân mới về vệ sinh cá nhân và phân khu sạch, bẩn.",en:"Train new workers on personal hygiene and clean and dirty zoning."}],mistakes:{vi:["Chỉ cách ly sản phẩm từ lúc phát hiện sai lệch thay vì từ lần giám sát đạt gần nhất.","Nhầm lẫn OPRP với CCP, đặt giới hạn tới hạn cho bước không đo lường được.","Ghi bù nhật ký giám sát sau ca, làm mất giá trị bằng chứng."],en:["Holding product only from when the deviation was found instead of from the last passing check.","Confusing OPRP with CCP and setting critical limits on steps that cannot be measured.","Back-filling monitoring logs after the shift, destroying their value as evidence."]},career:[{vi:"Nhân viên kiểm soát chất lượng (QC)",en:"Quality control officer"},{vi:"Chuyên viên an toàn thực phẩm",en:"Food safety specialist"},{vi:"Trưởng nhóm HACCP",en:"HACCP team leader"},{vi:"Giám đốc chất lượng & an toàn thực phẩm",en:"Quality & food safety director"}],glossary:[{term:"CCP",vi:"Điểm kiểm soát tới hạn: bước có giới hạn tới hạn đo được để kiểm soát mối nguy đáng kể.",en:"Critical control point: a step with a measurable critical limit controlling a significant hazard."},{term:"OPRP",vi:"Chương trình tiên quyết vận hành: biện pháp kiểm soát mối nguy đáng kể dùng tiêu chí hành động.",en:"Operational prerequisite programme: a control measure for a significant hazard using action criteria."},{term:"PRP",vi:"Chương trình tiên quyết: điều kiện nền về vệ sinh, nhà xưởng, kiểm soát động vật gây hại.",en:"Prerequisite programme: basic conditions such as hygiene, premises and pest control."},{term:"Critical limit",vi:"Giới hạn tới hạn: giá trị phân tách chấp nhận và không chấp nhận tại CCP.",en:"The value separating acceptable from unacceptable at a CCP."},{term:"Traceability",vi:"Truy xuất nguồn gốc: khả năng theo dõi lô hàng một bước trước và một bước sau trong chuỗi.",en:"Ability to follow a lot one step back and one step forward in the chain."}],quiz:[{q:{vi:"Điểm kiểm soát tới hạn (CCP) khác OPRP ở điểm nào?",en:"How does a CCP differ from an OPRP?"},options:{vi:["CCP chỉ áp dụng cho mối nguy vật lý","CCP có giới hạn tới hạn đo được, cho phép phát hiện kịp thời mất kiểm soát","OPRP không cần giám sát","OPRP chỉ dùng cho nhà xưởng"],en:["A CCP only covers physical hazards","A CCP has a measurable critical limit allowing timely detection of loss of control","An OPRP needs no monitoring","An OPRP only applies to buildings"]},answer:1,explain:{vi:"Theo ISO 22000:2018, CCP có giới hạn tới hạn đo được; OPRP dùng tiêu chí hành động có thể đo hoặc quan sát.",en:"Under ISO 22000:2018 a CCP has a measurable critical limit; an OPRP uses action criteria that can be measured or observed."}},{q:{vi:"Giám sát 1 giờ một lần, lần đạt cuối 13:00, phát hiện không đạt 14:00, dừng chuyền 14:30, công suất 800 gói/giờ. Có bao nhiêu gói nghi ngờ?",en:"Checks are hourly; last pass 13:00, fail found 14:00, line stopped 14:30, output 800 packs/hour. How many packs are suspect?"},options:{vi:["400","800","1600","1200"],en:["400","800","1600","1200"]},answer:3,explain:{vi:"Từ 13:00 đến 14:30 là 1.5 giờ x 800 gói/giờ = 1200 gói.",en:"From 13:00 to 14:30 is 1.5 hours x 800 packs/hour = 1200 packs."}},{q:{vi:"Trưởng ca yêu cầu xuất lô đang cách ly vì sai lệch CCP để kịp xe. Bạn làm gì?",en:"The shift leader wants to ship a lot on hold for a CCP deviation to catch the truck. What do you do?"},options:{vi:["Giữ lô, báo trưởng nhóm HACCP và chờ kết quả đánh giá","Xuất trước, xét nghiệm sau","Xuất một nửa lô","Đổi ngày sản xuất trên nhãn"],en:["Keep the hold, inform the HACCP leader and await the assessment","Ship now and test later","Ship half the lot","Change the production date on the label"]},answer:0,explain:{vi:"Sản phẩm sau sai lệch CCP chỉ được xuất khi đã đánh giá là an toàn; xuất sớm có thể gây ngộ độc và buộc thu hồi.",en:"Product after a CCP deviation ships only once assessed as safe; early release can cause illness and a recall."}},{q:{vi:"Theo Codex, hệ thống HACCP gồm bao nhiêu nguyên tắc?",en:"According to Codex, how many principles does HACCP have?"},options:{vi:["5 nguyên tắc","12 nguyên tắc","7 nguyên tắc","10 nguyên tắc"],en:["5 principles","12 principles","7 principles","10 principles"]},answer:2,explain:{vi:"HACCP có 7 nguyên tắc, nằm trong 12 bước áp dụng gồm 5 bước chuẩn bị ban đầu.",en:"HACCP has 7 principles within 12 application steps that include 5 preliminary steps."}}]}},"KK-953":{scenario:{company:"Golden Field Agri Services",supervisor:{name:"Hà Văn Lực",role:{vi:"Trưởng nhóm Kỹ thuật Bảo vệ thực vật",en:"Crop Protection Technical Lead"}},ref_code:"KC-0819",title:{vi:"Chẩn đoán đúng bệnh. Pha đúng liều. Bảo vệ người và ruộng.",en:"Right diagnosis. Right dose. Protect people and fields."},brief:{vi:"Bạn hoàn thiện phiếu khuyến cáo KC-0819 cho 2.5 ha lúa giai đoạn làm đòng. Triệu chứng: vết bệnh lan từ chóp và mép lá, gợn sóng màu vàng xám, sáng sớm có giọt dịch vàng đục; ruộng bón thừa đạm sau mưa bão. Thuốc đã duyệt (tên mô phỏng BX-35WP) dùng 400 g/ha; bình phun 16 L của nông dân đã hiệu chuẩn ở mức 320 L nước/ha. Sửa tác nhân gây bệnh và lượng thuốc mỗi bình, rồi lập báo cáo có căn cứ.",en:"You are completing advisory sheet KC-0819 for 2.5 ha of rice at panicle initiation. Symptoms: wavy yellowish-grey lesions spreading from leaf tips and margins, with turbid yellow droplets in the early morning; the field had excess nitrogen after a storm. The approved product (training name BX-35WP) is used at 400 g/ha; the farmers' 16 L sprayers are calibrated at 320 L of water per ha. Correct the pathogen and the product amount per tank, then write an evidence-based report."},reference_title:{vi:"Phiếu chẩn đoán & khuyến cáo đã duyệt · KC-0819",en:"Approved diagnosis & advisory sheet · KC-0819"},fields:[{id:"PATHOGEN",label:{vi:"Tác nhân gây bệnh",en:"Causal pathogen"},initial:"Pyricularia oryzae",expected:"Xanthomonas oryzae",choices:["Pyricularia oryzae","Xanthomonas oryzae","Rhizoctonia solani"],reference:"Kết quả giám định mẫu bệnh",hint:{vi:"Vết bệnh từ chóp, mép lá kèm giọt dịch vi khuẩn là bệnh bạc lá; đạo ôn có vết hình thoi, khô vằn nằm trên bẹ lá.",en:"Lesions from leaf tips and margins with bacterial ooze mean leaf blight; blast has diamond lesions and sheath blight sits on the sheath."}},{id:"DOSE_TANK",label:{vi:"Lượng thuốc mỗi bình 16 L (g)",en:"Product per 16 L tank (g)"},initial:"16",expected:"20",reference:"Biên bản hiệu chuẩn bình phun",ref_value:{vi:"Liều nhãn 400 g/ha; lượng nước hiệu chuẩn 320 L/ha; bình 16 L",en:"Label rate 400 g/ha; calibrated water volume 320 L/ha; 16 L tank"},hint:{vi:"Liều tính theo diện tích; số bình mỗi ha phụ thuộc lượng nước đã hiệu chuẩn, không mặc định 400 L/ha.",en:"The rate is per area; tanks per hectare depend on the calibrated water volume, not a default 400 L/ha."}}],sop32:{vi:"Lượng thuốc mỗi bình (g) = liều theo diện tích (g/ha) x dung tích bình (L) / lượng nước phun đã hiệu chuẩn (L/ha).",en:"Product per tank (g) = area rate (g/ha) x tank volume (L) / calibrated spray volume (L/ha)."},context:{label:"PHIẾU KHUYẾN CÁO NHÁP / KC-0819",metrics:[{label:{vi:"Diện tích",en:"Area"},value:"2.5 ha"},{label:{vi:"Liều nhãn mô phỏng",en:"Training label rate"},value:"400 g/ha"},{label:{vi:"Lượng nước hiệu chuẩn",en:"Calibrated spray volume"},value:"320 L/ha"}]},crisis:{vi:"Chủ nhiệm hợp tác xã nói: “Pha gấp đôi liều và trộn thêm gói thuốc đại lý quen bán, loại không có trong danh mục, cho chắc ăn. Dịch lan nhanh lắm, trên phiếu cứ ghi đúng liều là được.”",en:"The cooperative chairman says: “Mix a double dose and add the packet our dealer sells, the one not on the approved list, to be sure. The disease is spreading fast, just write the normal dose on the sheet.”"},options:{safe:{vi:"Từ chối pha gấp đôi và dùng thuốc ngoài danh mục; giữ liều đúng nhãn, hướng dẫn rút nước, ngừng bón đạm; báo cơ quan bảo vệ thực vật địa phương về ổ dịch và thuốc không rõ nguồn gốc.",en:"Refuse the double dose and the unapproved product; keep the label rate, advise draining and stopping nitrogen; report the outbreak and the unknown product to the local plant protection authority."},shortcut:{vi:"Pha gấp đôi liều, trộn thêm thuốc của đại lý cho nhanh, trên phiếu vẫn ghi liều chuẩn.",en:"Mix a double dose with the dealer's product and still write the standard dose on the sheet."},wait:{vi:"Không khuyến cáo gì thêm, để hợp tác xã tự quyết định cách phun.",en:"Give no further advice and let the cooperative decide how to spray."}},questions:{vi:["Vì sao tác nhân là Xanthomonas oryzae và mỗi bình 16 L cần 20 g thuốc? Dữ liệu nào chứng minh?","Bạn xử lý yêu cầu dùng thuốc ngoài danh mục, bảo đảm thời gian cách ly và an toàn cho người phun thế nào?"],en:["Why is the pathogen Xanthomonas oryzae and why does each 16 L tank need 20 g? Which data proves it?","How do you handle the request to use an unapproved product and ensure the pre-harvest interval and sprayer safety?"]},hints:{vi:["Đặt mô tả triệu chứng cạnh kết quả giám định và so với đặc điểm vết bệnh của từng tác nhân.","Tính số bình cần cho 1 ha từ lượng nước đã hiệu chuẩn rồi chia liều theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không khuyến cáo vượt liều nhãn hay thuốc ngoài danh mục; báo cáo cơ quan chuyên môn."],en:["Place the symptom description next to the lab result and compare lesion features for each pathogen.","Work out tanks per hectare from the calibrated volume, then split the rate as in SOP 3.2.","Re-read SOP 4.2: never advise above-label doses or unapproved products; report to the authority."]}},learning:{summary:{vi:"Kỹ sư nông học và bảo vệ thực vật theo dõi cây trồng trên đồng ruộng, chẩn đoán sâu bệnh, cỏ dại, thiếu dinh dưỡng và đưa ra khuyến cáo canh tác, phòng trừ theo hướng quản lý dịch hại tổng hợp (IPM). Nghề giúp năng suất ổn định, nông sản an toàn, giảm chi phí thuốc và bảo vệ môi trường; đòi hỏi kiến thức sinh học, kỹ năng điều tra đồng ruộng và tuân thủ nghiêm quy định về thuốc bảo vệ thực vật.",en:"An agronomist and crop protection specialist monitors crops in the field, diagnoses pests, diseases, weeds and nutrient deficiencies and gives farming and control advice based on integrated pest management (IPM). The role delivers stable yields, safe produce, lower pesticide costs and environmental protection; it requires biology, field scouting skills and strict compliance with pesticide rules."},responsibilities:{vi:["Điều tra định kỳ đồng ruộng, đánh giá mật độ sâu, tỷ lệ bệnh và ngưỡng phòng trừ.","Chẩn đoán dịch hại, lấy mẫu gửi giám định khi triệu chứng chưa rõ ràng.","Khuyến cáo biện pháp IPM: giống, thời vụ, phân bón, nước và thuốc bảo vệ thực vật khi cần.","Hướng dẫn nông dân hiệu chuẩn bình phun, pha đúng liều, dùng bảo hộ và tuân thủ thời gian cách ly.","Ghi nhật ký canh tác phục vụ truy xuất, chứng nhận VietGAP và kiểm soát dư lượng."],en:["Scout fields regularly and assess pest density, disease incidence and action thresholds.","Diagnose pests and send samples to the lab when symptoms are unclear.","Advise IPM measures: variety, timing, fertiliser, water and pesticides only when needed.","Teach farmers to calibrate sprayers, mix correct doses, wear protection and respect pre-harvest intervals.","Keep crop records for traceability, VietGAP certification and residue control."]},competencies:[{name:{vi:"Chẩn đoán dịch hại",en:"Pest and disease diagnosis"},desc:{vi:"Phân biệt triệu chứng do nấm, vi khuẩn, virus, côn trùng và thiếu dinh dưỡng ngoài đồng.",en:"Tell apart fungal, bacterial, viral, insect and nutrient symptoms in the field."}},{name:{vi:"Quản lý dịch hại tổng hợp",en:"Integrated pest management"},desc:{vi:"Phối hợp biện pháp canh tác, sinh học, cơ giới và hóa học theo ngưỡng kinh tế.",en:"Combine cultural, biological, mechanical and chemical measures based on economic thresholds."}},{name:{vi:"Dinh dưỡng & canh tác",en:"Nutrition & agronomy"},desc:{vi:"Xây dựng chế độ bón phân, tưới nước cân đối, hạn chế điều kiện phát sinh dịch.",en:"Plan balanced fertiliser and irrigation that limit conditions for outbreaks."}},{name:{vi:"Sử dụng thuốc an toàn",en:"Safe pesticide use"},desc:{vi:"Áp dụng nguyên tắc 4 đúng, hiệu chuẩn bình phun và bảo đảm thời gian cách ly.",en:"Apply the four rights, calibrate sprayers and enforce pre-harvest intervals."}},{name:{vi:"Khuyến nông & truyền đạt",en:"Extension & communication"},desc:{vi:"Giải thích dễ hiểu cho nông dân, thuyết phục bằng dữ liệu và mô hình trình diễn.",en:"Explain clearly to farmers and persuade with data and demonstration plots."}}],knowledge:{vi:["Luật Bảo vệ và kiểm dịch thực vật số 41/2013/QH13 và các văn bản hướng dẫn.","Danh mục thuốc bảo vệ thực vật được phép sử dụng tại Việt Nam do cơ quan quản lý nhà nước ban hành và cập nhật định kỳ.","Nguyên tắc 4 đúng: đúng thuốc, đúng liều lượng và nồng độ, đúng lúc, đúng cách.","VietGAP trồng trọt (TCVN 11892-1:2017) và giới hạn dư lượng tối đa (MRL) theo Codex.","Đặc điểm sinh học, triệu chứng các dịch hại chính trên lúa: đạo ôn, bạc lá, khô vằn, rầy nâu."],en:["Law on Plant Protection and Quarantine No. 41/2013/QH13 and its guiding documents.","The list of pesticides permitted in Vietnam, issued and periodically updated by the state authority.","The four rights: right product, right dose and concentration, right time, right method.","VietGAP for crops (TCVN 11892-1:2017) and Codex maximum residue limits (MRL).","Biology and symptoms of major rice pests: blast, bacterial leaf blight, sheath blight and brown planthopper."]},tools:["Kính lúp cầm tay & kính hiển vi hiện trường","Khung điều tra & bẫy đèn","Bình phun đeo vai & bộ hiệu chuẩn","Bộ test nhanh dư lượng thuốc","Ứng dụng nhật ký đồng ruộng"],kpis:{vi:["Tỷ lệ chẩn đoán đúng được xác nhận bằng giám định.","Lượng thuốc bảo vệ thực vật dùng trên mỗi ha so với vụ trước.","Tỷ lệ mẫu nông sản đạt giới hạn dư lượng (mục tiêu 100%).","Năng suất và lợi nhuận bình quân của các hộ được tư vấn."],en:["Share of diagnoses confirmed by lab tests.","Pesticide use per hectare versus the previous season.","Share of produce samples within residue limits (target 100%).","Average yield and profit of advised farms."]},day:[{time:"06:00",vi:"Điều tra ruộng sáng sớm, quan sát giọt dịch vi khuẩn và kiểm tra bẫy đèn.",en:"Scout fields at dawn, look for bacterial ooze and check light traps."},{time:"08:30",vi:"Lấy mẫu bệnh, chụp ảnh, ghi tọa độ ổ dịch và gửi phòng giám định.",en:"Collect diseased samples, photograph, record outbreak coordinates and send to the lab."},{time:"10:30",vi:"Hướng dẫn nông dân hiệu chuẩn bình phun và pha thuốc đúng liều.",en:"Show farmers how to calibrate sprayers and mix the correct dose."},{time:"14:00",vi:"Họp hợp tác xã, khuyến cáo biện pháp IPM và lịch bón phân điều chỉnh.",en:"Meet the cooperative to advise IPM measures and an adjusted fertiliser plan."},{time:"16:30",vi:"Cập nhật nhật ký đồng ruộng và gửi báo cáo dịch hại tuần.",en:"Update field records and send the weekly pest report."}],mistakes:{vi:["Chẩn đoán qua ảnh hoặc lời kể mà không thăm ruộng, nhầm bệnh vi khuẩn với bệnh nấm.","Pha thuốc theo kinh nghiệm hoặc mặc định 400 L/ha mà không hiệu chuẩn bình phun.","Khuyến cáo phun định kỳ theo lịch, bỏ qua ngưỡng phòng trừ và thiên địch."],en:["Diagnosing from photos or hearsay without visiting the field, mistaking bacterial for fungal disease.","Mixing doses by habit or assuming 400 L/ha without calibrating the sprayer.","Recommending calendar spraying and ignoring action thresholds and natural enemies."]},career:[{vi:"Kỹ thuật viên nông nghiệp",en:"Agricultural technician"},{vi:"Kỹ sư nông học & bảo vệ thực vật",en:"Agronomist & crop protection specialist"},{vi:"Trưởng vùng nguyên liệu",en:"Sourcing area manager"},{vi:"Chuyên gia quản lý cây trồng & phát triển bền vững",en:"Crop management & sustainability expert"}],glossary:[{term:"IPM",vi:"Quản lý dịch hại tổng hợp: phối hợp nhiều biện pháp, chỉ dùng thuốc khi dịch hại vượt ngưỡng.",en:"Integrated pest management: combining measures and using pesticides only above thresholds."},{term:"PHI",vi:"Thời gian cách ly: số ngày tối thiểu từ lần phun cuối đến khi thu hoạch.",en:"Pre-harvest interval: minimum days between the last spray and harvest."},{term:"MRL",vi:"Giới hạn dư lượng tối đa của thuốc bảo vệ thực vật được phép trong nông sản.",en:"Maximum residue limit of a pesticide permitted in produce."},{term:"Action threshold",vi:"Ngưỡng phòng trừ: mật độ dịch hại mà tại đó cần áp dụng biện pháp xử lý.",en:"Pest density at which control measures become necessary."},{term:"Sprayer calibration",vi:"Hiệu chuẩn bình phun: xác định lượng nước phun thực tế trên mỗi ha để tính liều.",en:"Measuring the actual spray volume per hectare to calculate the dose."}],quiz:[{q:{vi:"Vết bệnh hình thoi, tâm xám, viền nâu trên phiến lá lúa là đặc trưng của bệnh nào?",en:"Diamond-shaped leaf lesions with a grey centre and brown margin are typical of which rice disease?"},options:{vi:["Bạc lá","Khô vằn","Đạo ôn","Lem lép hạt"],en:["Bacterial leaf blight","Sheath blight","Rice blast","Grain discolouration"]},answer:2,explain:{vi:"Đạo ôn do nấm Pyricularia oryzae gây vết hình thoi (mắt én) tâm xám, viền nâu.",en:"Blast, caused by Pyricularia oryzae, produces diamond lesions with a grey centre and brown margin."}},{q:{vi:"Liều nhãn 300 g/ha, lượng nước hiệu chuẩn 400 L/ha, bình 20 L. Mỗi bình cần bao nhiêu gam thuốc?",en:"Label rate 300 g/ha, calibrated volume 400 L/ha, 20 L tank. How many grams per tank?"},options:{vi:["15 g","20 g","12 g","30 g"],en:["15 g","20 g","12 g","30 g"]},answer:0,explain:{vi:"Lượng thuốc mỗi bình = 300 x 20 / 400 = 15 g.",en:"Product per tank = 300 x 20 / 400 = 15 g."}},{q:{vi:"Nông dân muốn thu hoạch trước khi hết thời gian cách ly để kịp giá. Bạn khuyến cáo gì?",en:"A farmer wants to harvest before the pre-harvest interval ends to catch a good price. What do you advise?"},options:{vi:["Thu hoạch luôn vì dư lượng ít","Rửa kỹ rồi bán","Bán cho thương lái không cần nhật ký","Chờ đủ thời gian cách ly ghi trên nhãn và ghi nhật ký"],en:["Harvest now, residues are low","Wash well and sell","Sell to a trader without records","Wait for the full label interval and record it"]},answer:3,explain:{vi:"Thu hoạch trước thời gian cách ly có thể vượt MRL, gây hại người tiêu dùng và vi phạm quy định.",en:"Harvesting before the interval can exceed MRLs, harm consumers and break the rules."}},{q:{vi:"Nguyên tắc cốt lõi của IPM là gì?",en:"What is the core principle of IPM?"},options:{vi:["Phun định kỳ 7 ngày một lần","Kết hợp nhiều biện pháp, chỉ dùng thuốc khi dịch hại vượt ngưỡng","Chỉ dùng thuốc sinh học","Tăng liều để diệt triệt để"],en:["Spray every 7 days","Combine measures and use pesticides only above thresholds","Use only biopesticides","Raise doses to wipe pests out"]},answer:1,explain:{vi:"IPM ưu tiên biện pháp canh tác, sinh học, bảo vệ thiên địch và chỉ dùng thuốc khi cần thiết.",en:"IPM puts cultural and biological measures and natural enemies first and uses pesticides only when needed."}}]}},"KK-954":{scenario:{company:"Green Ridge Swine Farm",supervisor:{name:"Đinh Công Tuấn",role:{vi:"Bác sĩ thú y phụ trách trại",en:"Farm Veterinarian"}},ref_code:"TY-1108",title:{vi:"Bảo quản đúng. Tính liều theo cân. Ngừng thuốc đủ ngày.",en:"Store it right. Dose by weight. Respect withdrawal."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát nhật ký thú y TY-1108 khu nái. Trại vừa nhận lô vaccine lở mồm long móng vô hoạt dạng nhũ dầu. Nái N-217 viêm tử cung được chỉ định tiêm oxytetracycline tác dụng kéo dài liều 20 mg/kg, dung dịch 200 mg/mL; cân thực tế 236 kg, nhưng phiếu ghi khối lượng ước lượng 180 kg. Sửa điều kiện bảo quản vaccine và thể tích tiêm (mL), rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are reviewing veterinary log TY-1108 for the sow unit. The farm has just received inactivated oil-emulsion foot-and-mouth disease vaccine. Sow N-217 with metritis is prescribed long-acting oxytetracycline at 20 mg/kg, 200 mg/mL solution; she weighs 236 kg on the scale, but the sheet shows an estimated 180 kg. Correct the vaccine storage condition and the injection volume (mL), then write an evidence-based report."},reference_title:{vi:"Hướng dẫn sử dụng vaccine & đơn điều trị đã duyệt · TY-1108",en:"Approved vaccine leaflet & treatment order · TY-1108"},fields:[{id:"VACC_STORE",label:{vi:"Điều kiện bảo quản vaccine",en:"Vaccine storage condition"},initial:"-20°C",expected:"2-8°C",choices:["-20°C","2-8°C","15-25°C"],reference:"Tờ hướng dẫn sử dụng vaccine",hint:{vi:"Vaccine vô hoạt nhũ dầu phải bảo quản lạnh, tuyệt đối không để đông đá vì nhũ tương bị phá vỡ, mất hiệu lực.",en:"Inactivated oil-emulsion vaccine must be refrigerated and never frozen, as freezing breaks the emulsion and destroys potency."}},{id:"INJ_ML",label:{vi:"Thể tích tiêm cho nái N-217 (mL)",en:"Injection volume for sow N-217 (mL)"},initial:"18",expected:"23.6",reference:"Phiếu cân & đơn điều trị",ref_value:{vi:"Cân thực tế 236 kg; liều 20 mg/kg; nồng độ 200 mg/mL",en:"Weighed 236 kg; dose 20 mg/kg; concentration 200 mg/mL"},hint:{vi:"Liều thuốc tính theo khối lượng cân thực tế; ước lượng bằng mắt dễ gây thiếu liều và kháng thuốc.",en:"Dose by weighed body weight; visual estimates often cause underdosing and resistance."}}],sop32:{vi:"Thể tích tiêm (mL) = khối lượng cân thực tế (kg) x liều (mg/kg) / nồng độ thuốc (mg/mL); liều lớn chia nhiều vị trí tiêm theo hướng dẫn nhãn.",en:"Injection volume (mL) = weighed body weight (kg) x dose (mg/kg) / concentration (mg/mL); split large volumes across sites as the label directs."},context:{label:"NHẬT KÝ THÚ Y NHÁP / TY-1108",metrics:[{label:{vi:"Khối lượng cân",en:"Weighed body weight"},value:"236 kg"},{label:{vi:"Liều chỉ định",en:"Prescribed dose"},value:"20 mg/kg"},{label:{vi:"Nồng độ thuốc",en:"Concentration"},value:"200 mg/mL"},{label:{vi:"Ngừng thuốc mô phỏng",en:"Training withdrawal"},value:"28 d"}]},crisis:{vi:"Chủ trại nhắn: “Chiều nay thương lái đến bắt mấy nái loại, có cả con N-217 vừa tiêm hôm qua. Cứ cho xuất, sổ thì ghi là tiêm sau khi bán.”",en:"The farm owner messages you: “The trader is coming this afternoon for the cull sows, including N-217 that was injected yesterday. Let her go and record the injection as given after the sale.”"},options:{safe:{vi:"Không xuất nái N-217 khi chưa hết 28 ngày ngừng thuốc (mô phỏng), ghi sổ trung thực, báo bác sĩ thú y phụ trách trại và đề nghị hẹn thương lái sau ngày hết ngừng thuốc.",en:"Do not release sow N-217 before the 28-day withdrawal (training data) ends, keep honest records, inform the farm veterinarian and reschedule the trader after the withdrawal date."},shortcut:{vi:"Cho xuất bán N-217 cùng lô nái loại và ghi ngày tiêm lùi sau ngày bán.",en:"Sell N-217 with the cull sows and backdate the injection to after the sale."},wait:{vi:"Không ý kiến, để chủ trại và thương lái tự thỏa thuận.",en:"Say nothing and let the owner and the trader settle it."}},questions:{vi:["Vì sao vaccine phải bảo quản 2-8°C và nái N-217 cần 23.6 mL? Chứng từ nào chứng minh?","Bạn xử lý yêu cầu xuất bán nái đang trong thời gian ngừng thuốc thế nào để bảo vệ người tiêu dùng và uy tín trại?"],en:["Why must the vaccine be kept at 2-8°C and why does sow N-217 need 23.6 mL? Which documents prove it?","How do you handle the request to sell a sow still in withdrawal while protecting consumers and the farm's reputation?"]},hints:{vi:["Đọc tờ hướng dẫn vaccine và tìm dòng cảnh báo về nhiệt độ bảo quản.","Lấy khối lượng cân thực tế nhân liều rồi chia nồng độ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: vật nuôi trong thời gian ngừng thuốc không được xuất bán; mọi áp lực phải báo bác sĩ thú y."],en:["Read the vaccine leaflet and find the storage temperature warning.","Multiply the weighed body weight by the dose and divide by the concentration as in SOP 3.2.","Re-read SOP 4.2: animals in withdrawal are never sold; any pressure goes to the veterinarian."]}},learning:{summary:{vi:"Kỹ thuật viên chăn nuôi và thú y chăm sóc sức khỏe đàn vật nuôi hằng ngày: theo dõi biểu hiện, thực hiện lịch vaccine, điều trị theo chỉ định của bác sĩ thú y, vận hành an toàn sinh học, quản lý dinh dưỡng và ghi chép sổ sách. Nghề giúp giảm hao hụt, nâng năng suất và bảo đảm thực phẩm an toàn, không tồn dư kháng sinh; đòi hỏi kỹ năng thực hành, quan sát tinh và tuân thủ quy định thú y.",en:"A livestock and veterinary technician looks after herd health every day: observing animals, running the vaccination schedule, giving treatments prescribed by the veterinarian, operating biosecurity, managing nutrition and keeping records. The role cuts losses, raises productivity and keeps food safe and free of antibiotic residues; it requires hands-on skills, sharp observation and veterinary compliance."},responsibilities:{vi:["Theo dõi sức khỏe, ăn uống, thân nhiệt và phát hiện sớm vật nuôi bất thường.","Thực hiện lịch tiêm phòng, bảo quản vaccine đúng dây chuyền lạnh.","Cấp thuốc, tiêm điều trị theo đơn của bác sĩ thú y và tính liều theo khối lượng cân.","Vận hành an toàn sinh học: sát trùng, kiểm soát ra vào, cách ly, xử lý xác.","Ghi nhật ký điều trị, thời gian ngừng thuốc và báo cáo dịch bệnh theo quy định."],en:["Monitor health, feed intake and temperature and spot sick animals early.","Run the vaccination schedule and keep vaccines in the cold chain.","Give medicines and injections prescribed by the veterinarian, dosing by weighed body weight.","Operate biosecurity: disinfection, access control, isolation and carcass disposal.","Keep treatment and withdrawal records and report disease as required."]},competencies:[{name:{vi:"Phát hiện bệnh sớm",en:"Early disease detection"},desc:{vi:"Nhận biết thay đổi về ăn uống, hô hấp, phân, tư thế để báo bác sĩ thú y kịp thời.",en:"Notice changes in appetite, breathing, faeces and posture and alert the veterinarian quickly."}},{name:{vi:"Kỹ thuật tiêm & cấp thuốc",en:"Injection & dosing technique"},desc:{vi:"Tiêm đúng đường, đúng vị trí, đúng cỡ kim và tính liều chính xác theo khối lượng.",en:"Inject by the right route, site and needle size and calculate doses accurately by weight."}},{name:{vi:"Quản lý vaccine & dây chuyền lạnh",en:"Vaccine & cold chain management"},desc:{vi:"Bảo quản, vận chuyển và sử dụng vaccine đúng nhiệt độ, ghi số lô và hạn dùng.",en:"Store, transport and use vaccines at the right temperature, recording batch and expiry."}},{name:{vi:"An toàn sinh học",en:"Biosecurity"},desc:{vi:"Kiểm soát người, xe, vật tư ra vào trại và thực hiện quy trình sát trùng nghiêm ngặt.",en:"Control people, vehicles and supplies entering the farm and apply strict disinfection."}},{name:{vi:"Ghi chép & tuân thủ",en:"Records & compliance"},desc:{vi:"Ghi nhật ký trung thực, theo dõi thời gian ngừng thuốc và từ chối xuất bán sai quy định.",en:"Keep honest logs, track withdrawal periods and refuse non-compliant sales."}}],knowledge:{vi:["Luật Thú y số 79/2015/QH13 và các quy định về phòng, chống dịch bệnh động vật.","Luật Chăn nuôi số 32/2018/QH14 và quy định hạn chế sử dụng kháng sinh trong thức ăn chăn nuôi.","Thời gian ngừng thuốc và giới hạn dư lượng thuốc thú y tối đa (MRL) trong thực phẩm.","Tiêu chuẩn của Tổ chức Thú y Thế giới (WOAH) về an toàn sinh học và phúc lợi động vật.","Sử dụng kháng sinh có trách nhiệm: đúng chẩn đoán, đúng liều, đủ liệu trình, theo đơn thú y."],en:["Veterinary Law No. 79/2015/QH13 and rules on animal disease prevention and control.","Animal Husbandry Law No. 32/2018/QH14 and the restrictions on antibiotics in animal feed.","Withdrawal periods and maximum residue limits (MRL) for veterinary drugs in food.","World Organisation for Animal Health (WOAH) standards on biosecurity and animal welfare.","Responsible antibiotic use: correct diagnosis, correct dose, full course and veterinary prescription."]},tools:["Cân điện tử vật nuôi","Tủ lạnh vaccine có nhiệt kế tự ghi","Bơm tiêm tự động & kim theo cỡ","Nhiệt kế thú y","Phần mềm quản lý đàn"],kpis:{vi:["Tỷ lệ hao hụt, chết theo giai đoạn so với mục tiêu.","Tỷ lệ tiêm phòng đúng lịch, nhiệt độ tủ vaccine luôn trong 2-8°C.","Số vi phạm thời gian ngừng thuốc khi xuất bán (mục tiêu bằng 0).","Lượng kháng sinh sử dụng trên mỗi tấn thịt hơi."],en:["Mortality and losses by stage versus target.","On-schedule vaccination rate with the vaccine fridge always at 2-8°C.","Withdrawal violations at sale (target zero).","Antibiotic use per tonne of live weight."]},day:[{time:"06:30",vi:"Tắm sát trùng vào khu chăn nuôi, kiểm tra nhiệt độ tủ vaccine.",en:"Shower in to the production zone and check the vaccine fridge temperature."},{time:"07:30",vi:"Quan sát đàn, đo thân nhiệt các con bỏ ăn và ghi sổ theo dõi.",en:"Observe the herd, take temperatures of animals off feed and log them."},{time:"09:30",vi:"Tiêm phòng theo lịch, ghi số lô vaccine và vị trí tiêm.",en:"Vaccinate on schedule, recording vaccine batch and injection site."},{time:"14:00",vi:"Điều trị theo đơn của bác sĩ thú y, cân vật nuôi và tính liều.",en:"Treat as prescribed by the veterinarian, weigh animals and calculate doses."},{time:"16:30",vi:"Cập nhật nhật ký điều trị và danh sách vật nuôi đang ngừng thuốc.",en:"Update the treatment log and the list of animals in withdrawal."}],mistakes:{vi:["Ước lượng khối lượng bằng mắt, tiêm thiếu liều gây kháng thuốc hoặc thừa liều gây ngộ độc.","Để vaccine vô hoạt bị đông đá hoặc để ngoài nhiệt độ phòng quá lâu.","Xuất bán vật nuôi chưa hết thời gian ngừng thuốc, gây tồn dư trong thịt."],en:["Estimating weight by eye, underdosing and driving resistance or overdosing and causing toxicity.","Letting inactivated vaccine freeze or sit at room temperature too long.","Selling animals before the withdrawal period ends, leaving residues in meat."]},career:[{vi:"Công nhân chăn nuôi",en:"Stockperson"},{vi:"Kỹ thuật viên chăn nuôi & thú y",en:"Livestock & veterinary technician"},{vi:"Trưởng trại chăn nuôi",en:"Farm manager"},{vi:"Quản lý kỹ thuật chăn nuôi vùng",en:"Regional livestock technical manager"}],glossary:[{term:"Withdrawal period",vi:"Thời gian ngừng thuốc: từ lần dùng thuốc cuối đến khi được giết mổ hoặc khai thác sản phẩm.",en:"Time from the last dose until the animal may be slaughtered or its products used."},{term:"Biosecurity",vi:"An toàn sinh học: các biện pháp ngăn mầm bệnh xâm nhập và lây lan trong trại.",en:"Measures that keep pathogens out of the farm and stop them spreading."},{term:"Cold chain",vi:"Dây chuyền lạnh: giữ vaccine ở nhiệt độ quy định từ nhà sản xuất đến lúc tiêm.",en:"Keeping vaccines at the required temperature from the maker to the injection."},{term:"Inactivated vaccine",vi:"Vaccine vô hoạt: chứa mầm bệnh đã bị bất hoạt, thường có chất bổ trợ nhũ dầu.",en:"Vaccine containing killed pathogens, often with an oil-emulsion adjuvant."},{term:"MRL",vi:"Giới hạn dư lượng tối đa của thuốc thú y được phép trong thịt, sữa, trứng.",en:"Maximum residue limit of a veterinary drug allowed in meat, milk or eggs."}],quiz:[{q:{vi:"Lợn nặng 90 kg, liều 10 mg/kg, thuốc nồng độ 100 mg/mL. Cần tiêm bao nhiêu mL?",en:"A 90 kg pig, dose 10 mg/kg, drug at 100 mg/mL. How many mL are needed?"},options:{vi:["90 mL","0.9 mL","9 mL","10 mL"],en:["90 mL","0.9 mL","9 mL","10 mL"]},answer:2,explain:{vi:"Thể tích = 90 x 10 / 100 = 9 mL.",en:"Volume = 90 x 10 / 100 = 9 mL."}},{q:{vi:"Vaccine vô hoạt dạng nhũ dầu nên được bảo quản thế nào?",en:"How should inactivated oil-emulsion vaccine be stored?"},options:{vi:["2-8°C, không để đông đá","Đông đá ở -20°C","Nhiệt độ phòng","Ngâm trực tiếp trong nước đá"],en:["2-8°C, never frozen","Frozen at -20°C","Room temperature","Directly in ice water"]},answer:0,explain:{vi:"Đông đá làm vỡ nhũ tương và mất hiệu lực vaccine; phải giữ trong 2-8°C.",en:"Freezing breaks the emulsion and destroys potency; keep it at 2-8°C."}},{q:{vi:"Chủ trại muốn bán lợn đang trong thời gian ngừng thuốc. Bạn làm gì?",en:"The owner wants to sell pigs still in withdrawal. What do you do?"},options:{vi:["Đồng ý nếu lợn khỏe","Ghi lùi ngày tiêm","Giao cho thương lái quen","Từ chối, ghi sổ trung thực và báo bác sĩ thú y"],en:["Agree if the pigs look healthy","Backdate the injection","Hand them to a familiar trader","Refuse, keep honest records and inform the veterinarian"]},answer:3,explain:{vi:"Bán vật nuôi chưa hết thời gian ngừng thuốc gây tồn dư kháng sinh trong thịt, vi phạm quy định thú y và an toàn thực phẩm.",en:"Selling animals in withdrawal leaves antibiotic residues in meat and breaks veterinary and food safety rules."}},{q:{vi:"Thời gian ngừng thuốc là gì?",en:"What is a withdrawal period?"},options:{vi:["Thời gian thuốc phát huy tác dụng","Khoảng thời gian từ lần dùng thuốc cuối đến khi được giết mổ, khai thác sản phẩm","Hạn sử dụng của thuốc","Thời gian giữa hai mũi tiêm"],en:["Time for the drug to take effect","Time from the last dose until slaughter or product use is allowed","The drug's expiry date","Interval between two injections"]},answer:1,explain:{vi:"Thời gian ngừng thuốc bảo đảm dư lượng giảm dưới MRL trước khi thịt, sữa, trứng vào chuỗi thực phẩm.",en:"The withdrawal period ensures residues fall below the MRL before meat, milk or eggs enter the food chain."}}]}},"KK-955":{scenario:{company:"Tam Giang Aqua JSC",supervisor:{name:"Lâm Hoàng Phúc",role:{vi:"Giám đốc kỹ thuật trại nuôi",en:"Farm Technical Director"}},ref_code:"AO-A3-1104",title:{vi:"Đọc đúng nước ao. Chọn đúng hóa chất. Tính đúng liều.",en:"Read the water. Pick the right agent. Dose it right."},brief:{vi:"Bạn xử lý phiếu điều chỉnh môi trường AO-A3-1104 cho ao tôm thẻ chân trắng A3 (ngày nuôi 52). Ao rộng 2500 m2, mực nước đo thực tế 1.2 m (thiết kế 1.5 m). Độ kiềm đo được 100 mg/L CaCO3, mục tiêu 140 mg/L; pH dao động 7.9-8.4, TAN 2.1 mg/L. Dùng terminal đọc dữ liệu, sửa hóa chất tăng kiềm và khối lượng cần dùng (kg), rồi lập báo cáo có căn cứ.",en:"You are handling water-quality adjustment sheet AO-A3-1104 for whiteleg shrimp pond A3 (day 52). The pond is 2500 m2 with a measured water depth of 1.2 m (design 1.5 m). Alkalinity is 100 mg/L as CaCO3 against a target of 140 mg/L; pH swings 7.9-8.4 and TAN is 2.1 mg/L. Use the terminal to read the data, correct the alkalinity agent and the required amount (kg), then write an evidence-based report."},reference_title:{vi:"Nhật ký chất lượng nước & bảng liều hóa chất đã duyệt · AO-A3",en:"Approved water-quality log & dosing table · AO-A3"},fields:[{id:"ALK_AGENT",label:{vi:"Hóa chất tăng độ kiềm",en:"Alkalinity agent"},initial:"CaO",expected:"NaHCO3",choices:["CaO","NaHCO3","CaCO3"],reference:"Bảng lựa chọn hóa chất theo pH",hint:{vi:"pH và TAN cao thì phải tăng kiềm mà không đẩy pH: vôi nung làm tăng NH3 độc, CaCO3 tan kém khi pH trên 8.",en:"With high pH and TAN, raise alkalinity without pushing pH: quicklime increases toxic NH3 and CaCO3 dissolves poorly above pH 8."}},{id:"NAHCO3_KG",label:{vi:"Khối lượng hóa chất cần dùng (kg)",en:"Required amount (kg)"},initial:"252",expected:"201.6",reference:"Phiếu đo mực nước & độ kiềm",ref_value:{vi:"Diện tích 2500 m2; mực nước đo 1.2 m; kiềm 100 mg/L, mục tiêu 140 mg/L",en:"Area 2500 m2; measured depth 1.2 m; alkalinity 100 mg/L, target 140 mg/L"},hint:{vi:"Thể tích ao tính theo mực nước đo thực tế, không theo độ sâu thiết kế.",en:"Pond volume uses the measured water level, not the design depth."}}],sop32:{vi:"Khối lượng NaHCO3 (kg) = mức tăng kiềm (mg/L) x thể tích nước thực tế (m3) x 1.68 / 1000; thể tích = diện tích x mực nước đo.",en:"NaHCO3 (kg) = alkalinity increase (mg/L) x actual water volume (m3) x 1.68 / 1000; volume = area x measured depth."},context:{label:"AQUA-SCADA / AO-A3",metrics:[{label:{vi:"Diện tích ao",en:"Pond area"},value:"2500 m2"},{label:{vi:"Mực nước đo",en:"Measured depth"},value:"1.2 m"},{label:{vi:"Độ kiềm đo / mục tiêu",en:"Alkalinity now / target"},value:"100 / 140 mg/L"}]},crisis:{vi:"Quản lý trại nhắn: “Ao A5 bên cạnh nghi bị hoại tử gan tụy cấp, đêm nay xả hết nước ra kênh chung cho nhanh, đừng báo thú y kẻo cả vùng bị khoanh dịch.”",en:"The farm manager messages you: “Pond A5 next door looks like acute hepatopancreatic necrosis, drain it all into the shared canal tonight and don't tell the vets or the whole area will be quarantined.”"},options:{safe:{vi:"Không xả nước ao bệnh ra kênh; cách ly ao A5, xử lý nước trong ao theo quy trình diệt khuẩn đã duyệt, báo giám đốc kỹ thuật và cơ quan thú y địa phương, lấy mẫu xét nghiệm xác định bệnh.",en:"Do not drain the sick pond into the canal; isolate pond A5, disinfect the water in place per the approved procedure, inform the technical director and local veterinary authority and send samples for diagnosis."},shortcut:{vi:"Xả nước ao A5 ra kênh trong đêm và không báo cáo để tránh bị khoanh vùng dịch.",en:"Drain pond A5 into the canal overnight and report nothing to avoid quarantine."},wait:{vi:"Không can thiệp ao A5, chờ quản lý trại tự quyết định.",en:"Leave pond A5 alone and let the farm manager decide."}},questions:{vi:["Vì sao chọn NaHCO3 và cần 201.6 kg cho ao A3? Số liệu nào trong terminal chứng minh?","Bạn xử lý yêu cầu xả nước ao nghi nhiễm bệnh ra kênh chung thế nào để đúng quy định và bảo vệ cả vùng nuôi?"],en:["Why did you choose NaHCO3 and why does pond A3 need 201.6 kg? Which terminal data proves it?","How do you handle the request to drain a suspected diseased pond into the shared canal lawfully while protecting the whole farming area?"]},hints:{vi:["Chạy cat water.log và cat dosing.txt, so pH, TAN với điều kiện dùng từng hóa chất.","Lấy thể tích từ mực nước trong cat level.log rồi áp dụng công thức SOP mục 3.2.","Đọc lại SOP mục 4.2: nước ao nghi nhiễm bệnh phải được xử lý trước khi thải và phải báo cơ quan thú y."],en:["Run cat water.log and cat dosing.txt and compare pH and TAN with each agent's conditions.","Take the volume from the level in cat level.log and apply the SOP 3.2 formula.","Re-read SOP 4.2: water from a suspected diseased pond must be treated before discharge and reported to the vets."]},terminal:{system:"aqua-scada",settable:["ALK_AGENT","NAHCO3_KG"],commands:[{cmd:"status",out:{vi:"Ao A3 · tôm thẻ ngày 52 · mật độ 120 con/m2 · 6 máy quạt nước đang chạy · cảnh báo: độ kiềm thấp",en:"Pond A3 · whiteleg shrimp day 52 · 120 shrimp/m2 · 6 paddlewheels running · alert: low alkalinity"}},{cmd:"cat water.log",out:{vi:"06:00 pH 7.9, DO 4.3 mg/L · 14:00 pH 8.4 · kiềm 100 mg/L CaCO3 · TAN 2.1 mg/L · nhiệt độ 30°C",en:"06:00 pH 7.9, DO 4.3 mg/L · 14:00 pH 8.4 · alkalinity 100 mg/L CaCO3 · TAN 2.1 mg/L · 30°C"}},{cmd:"cat level.log",out:{vi:"Cảm biến mực nước A3: 1.20 m (thiết kế 1.50 m) · hao hụt do bốc hơi, chưa cấp bù",en:"Pond A3 level sensor: 1.20 m (design 1.50 m) · evaporation loss, not yet topped up"}},{cmd:"cat dosing.txt",out:{vi:"NaHCO3: 1.68 kg/1000 m3 cho mỗi 1 mg/L kiềm · CaO: tăng pH nhanh, không dùng khi TAN cao · CaCO3: tan kém khi pH trên 8",en:"NaHCO3: 1.68 kg per 1000 m3 per 1 mg/L alkalinity · CaO: raises pH fast, not with high TAN · CaCO3: dissolves poorly above pH 8"}},{cmd:"cat target.txt",out:{vi:"Mục tiêu tuần: kiềm 140 mg/L CaCO3 · pH dao động ngày không quá 0.5 · DO sáng sớm ≥ 4 mg/L",en:"Weekly targets: alkalinity 140 mg/L CaCO3 · daily pH swing no more than 0.5 · dawn DO ≥ 4 mg/L"}}]}},learning:{summary:{vi:"Kỹ sư nuôi trồng thủy sản thiết kế, vận hành và tối ưu hệ thống nuôi tôm, cá: chuẩn bị ao, quản lý chất lượng nước, thức ăn, sức khỏe vật nuôi, an toàn sinh học và xử lý nước thải. Nghề quyết định tỷ lệ sống, hệ số chuyển đổi thức ăn và giá thành mỗi kg sản phẩm; đòi hỏi hiểu hóa học nước, sinh học vật nuôi, vận hành thiết bị và tuân thủ quy định thú y, môi trường.",en:"An aquaculture engineer designs, operates and optimises shrimp and fish farming systems: pond preparation, water quality, feed, animal health, biosecurity and effluent treatment. The role drives survival rate, feed conversion and cost per kilogram; it requires water chemistry, animal biology, equipment operation and compliance with veterinary and environmental rules."},responsibilities:{vi:["Lập kế hoạch vụ nuôi: chuẩn bị ao, chọn giống sạch bệnh, mật độ thả và lịch cho ăn.","Đo và điều chỉnh chất lượng nước: DO, pH, độ kiềm, TAN, nitrit, độ mặn.","Quản lý thức ăn, theo dõi tăng trưởng, hệ số chuyển đổi thức ăn (FCR) và tỷ lệ sống.","Vận hành hệ thống quạt nước, lọc, ao lắng và xử lý nước thải.","Giám sát sức khỏe, an toàn sinh học và phối hợp với thú y khi có dấu hiệu dịch bệnh."],en:["Plan the crop: pond preparation, disease-free seed, stocking density and feeding schedule.","Measure and adjust water quality: DO, pH, alkalinity, TAN, nitrite and salinity.","Manage feed and track growth, feed conversion ratio (FCR) and survival.","Run aerators, filters, settling ponds and effluent treatment.","Monitor health and biosecurity and work with the vets at the first sign of disease."]},competencies:[{name:{vi:"Hóa học & sinh học nước",en:"Water chemistry & biology"},desc:{vi:"Hiểu quan hệ pH, độ kiềm, CO2, tảo, amoniac và oxy hòa tan trong ao.",en:"Understand how pH, alkalinity, CO2, algae, ammonia and dissolved oxygen interact."}},{name:{vi:"Quản lý thức ăn & tăng trưởng",en:"Feed & growth management"},desc:{vi:"Điều chỉnh lượng ăn theo nhá, sức khỏe và thời tiết để tối ưu FCR.",en:"Adjust feeding by tray checks, health and weather to optimise FCR."}},{name:{vi:"Vận hành hệ thống nuôi",en:"System operation"},desc:{vi:"Vận hành, bảo trì quạt nước, máy thổi khí, cảm biến và hệ thống xử lý nước.",en:"Operate and maintain paddlewheels, blowers, sensors and water treatment."}},{name:{vi:"An toàn sinh học thủy sản",en:"Aquatic biosecurity"},desc:{vi:"Ngăn mầm bệnh xâm nhập qua giống, nước, dụng cụ và xử lý ao bệnh đúng quy trình.",en:"Keep pathogens out via seed, water and tools and handle diseased ponds correctly."}},{name:{vi:"Ra quyết định dựa trên dữ liệu",en:"Data-driven decisions"},desc:{vi:"Dùng số đo thực tế để tính liều hóa chất, lượng ăn và thời điểm thu hoạch.",en:"Use real measurements to set chemical doses, feed rates and harvest timing."}}],knowledge:{vi:["Luật Thủy sản số 18/2017/QH14 và các quy định về điều kiện cơ sở nuôi trồng thủy sản.","Luật Thú y số 79/2015/QH13 về phòng, chống dịch bệnh động vật thủy sản.","Cân bằng CO2, pH, độ kiềm và tỷ lệ amoniac tự do (NH3) tăng theo pH, nhiệt độ.","VietGAP trong nuôi trồng thủy sản và các tiêu chuẩn nuôi có trách nhiệm.","Các bệnh chính trên tôm: hoại tử gan tụy cấp (AHPND), đốm trắng (WSSV), vi bào tử trùng (EHP)."],en:["Fisheries Law No. 18/2017/QH14 and rules on aquaculture facility conditions.","Veterinary Law No. 79/2015/QH13 on aquatic animal disease prevention and control.","The CO2, pH and alkalinity balance and how free ammonia (NH3) rises with pH and temperature.","VietGAP for aquaculture and responsible farming standards.","Major shrimp diseases: acute hepatopancreatic necrosis (AHPND), white spot (WSSV) and EHP."]},tools:["Máy đo DO, pH cầm tay","Bộ test kiềm, TAN, nitrit","Cảm biến chất lượng nước trực tuyến","Máy quạt nước & máy thổi khí","Phần mềm quản lý vụ nuôi"],kpis:{vi:["Tỷ lệ sống đến khi thu hoạch.","Hệ số chuyển đổi thức ăn (FCR) so với mục tiêu.","Giá thành sản xuất trên mỗi kg tôm.","Số ngày chỉ tiêu nước nằm ngoài ngưỡng an toàn."],en:["Survival rate at harvest.","Feed conversion ratio (FCR) versus target.","Production cost per kilogram of shrimp.","Days with water parameters outside safe limits."]},day:[{time:"05:30",vi:"Đo DO, pH sáng sớm và kiểm tra hoạt động của quạt nước.",en:"Measure dawn DO and pH and check the paddlewheels."},{time:"07:00",vi:"Cho ăn cữ sáng, kiểm tra nhá để điều chỉnh lượng thức ăn.",en:"Give the morning feed and check trays to adjust the ration."},{time:"10:00",vi:"Đo độ kiềm, TAN, nitrit và quyết định bổ sung hóa chất.",en:"Test alkalinity, TAN and nitrite and decide on chemical additions."},{time:"14:00",vi:"Đo pH buổi chiều, chài mẫu kiểm tra tăng trưởng và sức khỏe tôm.",en:"Measure afternoon pH and cast-net samples to check growth and health."},{time:"17:00",vi:"Cập nhật nhật ký ao và lập kế hoạch cho ngày hôm sau.",en:"Update the pond log and plan the next day."}],mistakes:{vi:["Tính liều hóa chất theo độ sâu thiết kế thay vì mực nước thực tế.","Dùng vôi nung khi pH và TAN cao, làm tăng amoniac tự do gây độc cho tôm.","Xả nước ao bệnh chưa xử lý ra kênh chung, làm lây dịch cho cả vùng."],en:["Dosing chemicals by design depth instead of the actual water level.","Using quicklime with high pH and TAN, raising toxic free ammonia.","Draining untreated water from a diseased pond into the shared canal and spreading disease."]},career:[{vi:"Kỹ thuật viên ao nuôi",en:"Pond technician"},{vi:"Kỹ sư nuôi trồng thủy sản",en:"Aquaculture engineer"},{vi:"Trưởng trại nuôi",en:"Farm manager"},{vi:"Giám đốc kỹ thuật vùng nuôi",en:"Regional aquaculture technical director"}],glossary:[{term:"FCR",vi:"Hệ số chuyển đổi thức ăn: số kg thức ăn cần để tạo 1 kg tăng trọng.",en:"Feed conversion ratio: kilograms of feed per kilogram of weight gain."},{term:"TAN",vi:"Tổng amoni (NH3 + NH4+) trong nước; phần NH3 tự do là dạng độc với tôm cá.",en:"Total ammonia nitrogen (NH3 + NH4+); the free NH3 fraction is toxic to shrimp and fish."},{term:"Alkalinity",vi:"Độ kiềm: khả năng đệm pH của nước, tính bằng mg/L CaCO3.",en:"The water's pH buffering capacity, expressed as mg/L CaCO3."},{term:"DO",vi:"Oxy hòa tan trong nước, thường thấp nhất vào sáng sớm.",en:"Dissolved oxygen in water, usually lowest at dawn."},{term:"Biosecurity",vi:"An toàn sinh học: biện pháp ngăn mầm bệnh xâm nhập và lây lan giữa các ao, các trại.",en:"Measures preventing pathogens from entering and spreading between ponds and farms."}],quiz:[{q:{vi:"Khi pH tăng, tỷ lệ amoniac tự do (NH3) trong tổng amoni thay đổi thế nào?",en:"As pH rises, how does the share of free ammonia (NH3) in total ammonia change?"},options:{vi:["Giảm","Không đổi","Tăng","Bằng không"],en:["Decreases","Stays the same","Increases","Drops to zero"]},answer:2,explain:{vi:"pH càng cao, cân bằng càng chuyển về NH3 tự do, dạng độc với tôm cá.",en:"The higher the pH, the more the balance shifts to free NH3, the toxic form."}},{q:{vi:"Ao 4000 m2, mực nước 1 m, cần tăng kiềm 20 mg/L; hệ số 1.68 kg NaHCO3/1000 m3 cho mỗi 1 mg/L. Cần bao nhiêu kg?",en:"A 4000 m2 pond at 1 m depth needs 20 mg/L more alkalinity; factor 1.68 kg NaHCO3 per 1000 m3 per 1 mg/L. How many kg?"},options:{vi:["134.4 kg","168 kg","80 kg","33.6 kg"],en:["134.4 kg","168 kg","80 kg","33.6 kg"]},answer:0,explain:{vi:"Khối lượng = 20 x 4000 x 1.68 / 1000 = 134.4 kg.",en:"Amount = 20 x 4000 x 1.68 / 1000 = 134.4 kg."}},{q:{vi:"Ao nghi nhiễm bệnh, quản lý muốn xả nước ra kênh chung ngay. Bạn làm gì?",en:"A pond is suspected of disease and the manager wants to drain it into the canal now. What do you do?"},options:{vi:["Xả vào ban đêm","Pha loãng rồi xả","Bơm sang ao khác","Cách ly, xử lý nước trong ao và báo cơ quan thú y"],en:["Drain it at night","Dilute and drain","Pump it into another pond","Isolate, treat the water in place and notify the vets"]},answer:3,explain:{vi:"Xả nước ao bệnh chưa xử lý làm lây lan dịch cho cả vùng và vi phạm quy định thú y, môi trường.",en:"Draining untreated diseased water spreads infection across the area and breaks veterinary and environmental rules."}},{q:{vi:"FCR bằng 1.3 nghĩa là gì?",en:"What does an FCR of 1.3 mean?"},options:{vi:["1.3 tấn tôm mỗi ha","Cần 1.3 kg thức ăn để tạo 1 kg tôm tăng trọng","Tỷ lệ sống 130%","Cho ăn 1.3 lần mỗi ngày"],en:["1.3 tonnes of shrimp per ha","1.3 kg of feed produces 1 kg of shrimp gain","130% survival","1.3 feedings per day"]},answer:1,explain:{vi:"FCR là tỷ lệ giữa lượng thức ăn tiêu thụ và khối lượng tăng trọng; càng thấp càng hiệu quả.",en:"FCR is feed consumed divided by weight gained; lower is more efficient."}}]}},"KK-956":{scenario:{company:"Phu Loc Grain JSC",supervisor:{name:"Nguyễn Thị Kim Oanh",role:{vi:"Trưởng phòng Thu mua nguyên liệu",en:"Head of Raw Material Procurement"}},ref_code:"PO-LUA-2611",title:{vi:"Đúng điều kiện giao. Đúng quy đổi ẩm. Công bằng với nông dân.",en:"Right delivery term. Right moisture math. Fair to farmers."},brief:{vi:"Bạn hoàn thiện đơn mua PO-LUA-2611 với một hợp tác xã theo hợp đồng liên kết đã ký: hợp tác xã chịu cước và giao lúa tới kho nhà máy. Phiếu cân xe ghi 21500 kg lúa tươi, ẩm độ đo có chứng kiến 17%; hợp đồng thanh toán theo ẩm độ chuẩn 14%, giá mô phỏng 7200 đồng/kg. Sửa điều kiện giao hàng và khối lượng quy đổi, rồi lập báo cáo có căn cứ để giải thích minh bạch với hợp tác xã.",en:"You are finalising purchase order PO-LUA-2611 with a cooperative under the signed linkage contract: the cooperative pays freight and delivers paddy to the mill warehouse. The weighbridge slip shows 21500 kg of fresh paddy at 17% moisture measured before witnesses; the contract pays at a standard 14% moisture and a training price of 7200 VND/kg. Correct the delivery term and the adjusted weight, then write an evidence-based report you can explain openly to the cooperative."},reference_title:{vi:"Hợp đồng liên kết & phiếu cân, đo ẩm đã ký · PO-LUA-2611",en:"Signed linkage contract & weighbridge-moisture slip · PO-LUA-2611"},fields:[{id:"INCOTERM",label:{vi:"Điều kiện giao hàng trên đơn mua",en:"Delivery term on the PO"},initial:"EXW",expected:"DAP",choices:["EXW","FCA","DAP"],reference:"Điều 4 hợp đồng liên kết",hint:{vi:"Bên bán chịu cước và giao tới kho người mua là DAP; ghi EXW khiến nhà máy trả cước trùng và dễ tranh chấp.",en:"The seller paying freight to the buyer's warehouse is DAP; EXW makes the mill pay freight twice and invites disputes."}},{id:"NET_KG",label:{vi:"Khối lượng quy đổi ẩm độ 14% (kg)",en:"Weight adjusted to 14% moisture (kg)"},initial:"20855",expected:"20750",reference:"Phiếu cân & đo ẩm có chứng kiến",ref_value:{vi:"Lúa tươi 21500 kg; ẩm độ đo 17%; ẩm độ chuẩn 14%",en:"Fresh paddy 21500 kg; measured moisture 17%; standard moisture 14%"},hint:{vi:"Quy đổi phải giữ nguyên lượng chất khô; trừ 1% khối lượng cho mỗi 1% ẩm là cách gần đúng, sai hợp đồng.",en:"The conversion must keep dry matter constant; deducting 1% weight per 1% moisture is an approximation that breaches the contract."}}],sop32:{vi:"Khối lượng quy đổi = khối lượng cân x (100 - ẩm độ thực tế) / (100 - ẩm độ chuẩn); thành tiền = khối lượng quy đổi x đơn giá hợp đồng (mô phỏng).",en:"Adjusted weight = weighed mass x (100 - actual moisture) / (100 - standard moisture); payment = adjusted weight x contract price (training data)."},context:{label:"ĐƠN MUA NHÁP / PO-LUA-2611",metrics:[{label:{vi:"Khối lượng cân",en:"Weighbridge weight"},value:"21500 kg"},{label:{vi:"Ẩm độ đo / chuẩn",en:"Moisture actual / standard"},value:"17% / 14%"},{label:{vi:"Đơn giá mô phỏng",en:"Training price"},value:"7200 VND/kg"}]},crisis:{vi:"Chủ nhiệm hợp tác xã nhắn riêng: “Em ghi 20855 kg theo kiểu trừ 1% mỗi độ ẩm nhé, anh gửi em 2 triệu tiền bồi dưỡng. Bên anh quen tính vậy rồi, kế toán không để ý đâu.”",en:"The cooperative chairman messages you privately: “Write 20855 kg using the 1% per moisture point method and I'll send you 2 million VND as a thank-you. We always calculate it that way and accounting never notices.”"},options:{safe:{vi:"Từ chối khoản bồi dưỡng, giữ 20750 kg theo công thức hợp đồng, báo trưởng phòng thu mua và kênh tuân thủ; giải thích minh bạch cách quy đổi và mời đo lại ẩm độ có chứng kiến nếu còn băn khoăn.",en:"Decline the payment, keep 20750 kg per the contract formula, inform the procurement head and compliance; explain the conversion openly and offer a witnessed re-test if doubts remain."},shortcut:{vi:"Nhận khoản bồi dưỡng và ghi 20855 kg vì chênh lệch nhỏ, giữ quan hệ tốt với hợp tác xã.",en:"Accept the payment and write 20855 kg since the gap is small and the relationship matters."},wait:{vi:"Chưa duyệt đơn mua, để kế toán và hợp tác xã tự thỏa thuận khối lượng.",en:"Leave the PO unapproved and let accounting and the cooperative agree the weight."}},questions:{vi:["Vì sao điều kiện giao là DAP và khối lượng thanh toán là 20750 kg? Điều khoản và phiếu nào chứng minh?","Bạn giữ quan hệ hợp tác lâu dài với hợp tác xã thế nào khi từ chối khoản bồi dưỡng và cách tính quen thuộc của họ?"],en:["Why is the delivery term DAP and the payable weight 20750 kg? Which clause and slip prove it?","How do you keep a long-term partnership with the cooperative while refusing the payment and their usual calculation?"]},hints:{vi:["Đọc Điều 4 hợp đồng liên kết: ai chịu cước và hàng được giao tại đâu.","Quy đổi theo lượng chất khô: nhân khối lượng với (100 - ẩm thực tế) rồi chia (100 - ẩm chuẩn) theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi khoản quà, tiền bồi dưỡng từ nhà cung cấp phải từ chối và báo cáo."],en:["Read clause 4 of the linkage contract: who pays freight and where delivery takes place.","Convert on dry matter: multiply weight by (100 - actual moisture) and divide by (100 - standard) as in SOP 3.2.","Re-read SOP 4.2: any gift or payment from a supplier must be declined and reported."]}},learning:{summary:{vi:"Chuyên viên thu mua nông sản và hợp tác xã xây dựng, quản lý vùng nguyên liệu ổn định cho nhà máy: đàm phán hợp đồng liên kết với hợp tác xã, nông hộ, kiểm soát chất lượng đầu vào, quy đổi khối lượng, định giá minh bạch và hỗ trợ truy xuất nguồn gốc. Nghề cần hiểu nông học cơ bản, thị trường hàng hóa, hợp đồng và đặc biệt là sự công bằng, liêm chính trong quan hệ với người nông dân.",en:"An agricultural sourcing and cooperative officer builds and manages a stable raw material base for the mill: negotiating linkage contracts with cooperatives and farmers, controlling incoming quality, adjusting weights, pricing transparently and supporting traceability. The role needs basic agronomy, commodity market and contract knowledge and, above all, fairness and integrity with farmers."},responsibilities:{vi:["Phát triển và đánh giá hợp tác xã, tổ hợp tác, nông hộ đủ điều kiện liên kết.","Đàm phán giá, chất lượng, điều kiện giao hàng và thanh toán trong hợp đồng liên kết.","Lập kế hoạch thu mua theo mùa vụ, điều phối cân, đo ẩm, kiểm tra chất lượng tại điểm nhận.","Tính khối lượng quy đổi, giá trị thanh toán và giải quyết khiếu nại minh bạch.","Theo dõi rủi ro giá, thời tiết, dịch hại và hỗ trợ kỹ thuật, truy xuất cho vùng nguyên liệu."],en:["Develop and assess cooperatives, farmer groups and households eligible for linkage.","Negotiate price, quality, delivery and payment terms in linkage contracts.","Plan seasonal buying and coordinate weighing, moisture testing and quality checks at intake.","Calculate adjusted weights and payments and resolve complaints transparently.","Track price, weather and pest risks and support agronomy and traceability in the sourcing area."]},competencies:[{name:{vi:"Đàm phán & quan hệ đối tác",en:"Negotiation & partnership"},desc:{vi:"Tìm giải pháp cùng có lợi, giữ cam kết dài hạn với hợp tác xã qua nhiều mùa vụ.",en:"Find win-win terms and keep long-term commitments with cooperatives across seasons."}},{name:{vi:"Kiểm soát chất lượng nông sản",en:"Produce quality control"},desc:{vi:"Lấy mẫu đại diện, đo ẩm, tạp chất, hạt hư và phân hạng theo tiêu chuẩn hợp đồng.",en:"Take representative samples, test moisture, impurities and damaged grain and grade by contract."}},{name:{vi:"Tính toán quy đổi & giá",en:"Weight and price calculation"},desc:{vi:"Quy đổi khối lượng theo ẩm độ, tạp chất và tính thanh toán chính xác, kiểm chứng được.",en:"Adjust weights for moisture and impurities and calculate payments accurately and verifiably."}},{name:{vi:"Hiểu biết hợp đồng",en:"Contract literacy"},desc:{vi:"Nắm điều khoản giá sàn, điều kiện giao hàng, phạt vi phạm và xử lý tranh chấp.",en:"Understand floor price, delivery terms, penalties and dispute resolution clauses."}},{name:{vi:"Liêm chính & minh bạch",en:"Integrity & transparency"},desc:{vi:"Từ chối quà, tiền bồi dưỡng, công khai cách tính để nông dân tin tưởng.",en:"Refuse gifts and payments and publish calculations so farmers can trust them."}}],knowledge:{vi:["Luật Hợp tác xã số 17/2023/QH15 về tổ chức và hoạt động của hợp tác xã.","Nghị định 98/2018/NĐ-CP về chính sách khuyến khích hợp tác, liên kết trong sản xuất và tiêu thụ sản phẩm nông nghiệp.","Bộ luật Dân sự 2015 về giao kết, thực hiện hợp đồng và Incoterms 2020 về điều kiện giao hàng.","Phương pháp quy đổi khối lượng theo ẩm độ, tạp chất và tiêu chuẩn chất lượng hạt.","Truy xuất nguồn gốc, VietGAP và yêu cầu bền vững của khách hàng xuất khẩu."],en:["Law on Cooperatives No. 17/2023/QH15 on the organisation and operation of cooperatives.","Decree 98/2018/ND-CP on incentives for cooperation and linkage in agricultural production and sales.","Civil Code 2015 on concluding and performing contracts, and Incoterms 2020 delivery terms.","Methods for adjusting weight by moisture and impurities and grain quality standards.","Traceability, VietGAP and the sustainability requirements of export customers."]},tools:["Máy đo ẩm độ hạt đã hiệu chuẩn","Cân xe & cân bàn","Bộ chia mẫu và sàng tạp chất","Phần mềm quản lý thu mua (ERP)","Ứng dụng truy xuất vùng nguyên liệu"],kpis:{vi:["Tỷ lệ sản lượng thu mua qua hợp đồng liên kết so với kế hoạch.","Giá mua bình quân so với giá thị trường tham chiếu.","Số khiếu nại của hợp tác xã về cân, ẩm độ, thanh toán.","Tỷ lệ hợp tác xã tái ký hợp đồng mùa vụ sau."],en:["Share of volume bought under linkage contracts versus plan.","Average purchase price versus the reference market price.","Cooperative complaints about weighing, moisture and payment.","Share of cooperatives renewing for the next season."]},day:[{time:"06:00",vi:"Có mặt điểm thu mua, kiểm tra hiệu chuẩn máy đo ẩm và cân xe.",en:"Arrive at the intake point and check the moisture meter and weighbridge calibration."},{time:"08:00",vi:"Nhận xe lúa, lấy mẫu đại diện và đo ẩm có chứng kiến của hợp tác xã.",en:"Receive paddy trucks, take representative samples and test moisture with cooperative witnesses."},{time:"11:00",vi:"Họp hợp tác xã về kế hoạch vụ sau, giá sàn và hỗ trợ kỹ thuật.",en:"Meet the cooperative on next season's plan, floor price and technical support."},{time:"14:00",vi:"Lập đơn mua, tính khối lượng quy đổi và chuyển hồ sơ cho kế toán.",en:"Issue purchase orders, calculate adjusted weights and pass files to accounting."},{time:"16:30",vi:"Cập nhật bảng theo dõi giá thị trường và rủi ro thời tiết vùng nguyên liệu.",en:"Update the market price tracker and weather risk for the sourcing area."}],mistakes:{vi:["Trừ 1% khối lượng cho mỗi 1% ẩm thay vì quy đổi theo lượng chất khô.","Ghi sai điều kiện giao hàng, khiến công ty trả cước trùng hoặc tranh chấp trách nhiệm.","Nhận quà, tiền bồi dưỡng từ hợp tác xã, mất tính độc lập khi kiểm tra chất lượng."],en:["Deducting 1% weight per 1% moisture instead of converting on dry matter.","Recording the wrong delivery term so the company pays freight twice or disputes liability.","Accepting gifts or payments from cooperatives and losing independence in quality checks."]},career:[{vi:"Nhân viên thu mua nông sản",en:"Agricultural buyer"},{vi:"Chuyên viên phát triển vùng nguyên liệu",en:"Sourcing area development officer"},{vi:"Trưởng phòng thu mua",en:"Head of procurement"},{vi:"Giám đốc chuỗi cung ứng nông sản",en:"Agri-food supply chain director"}],glossary:[{term:"Hợp đồng liên kết",vi:"Hợp đồng giữa doanh nghiệp và hợp tác xã, nông hộ về sản xuất và tiêu thụ nông sản theo kế hoạch.",en:"A contract between a company and cooperatives or farmers on planned production and sale of produce."},{term:"Standard moisture",vi:"Ẩm độ chuẩn: mức ẩm thỏa thuận làm căn cứ quy đổi khối lượng thanh toán.",en:"The agreed moisture level used as the basis for payable weight."},{term:"DAP",vi:"Điều kiện Incoterms: người bán chịu chi phí, rủi ro đưa hàng tới nơi đến chỉ định, chưa dỡ hàng.",en:"Incoterms rule where the seller bears cost and risk to the named destination, not unloaded."},{term:"Floor price",vi:"Giá sàn: mức giá tối thiểu doanh nghiệp cam kết mua dù giá thị trường giảm.",en:"The minimum price the buyer commits to pay even if the market falls."},{term:"Traceability",vi:"Truy xuất nguồn gốc: khả năng xác định lô nông sản đến từ vùng, hộ sản xuất nào.",en:"The ability to trace a lot back to its growing area and farm."}],quiz:[{q:{vi:"10000 kg lúa ẩm độ 20% quy đổi về ẩm độ chuẩn 14% được khoảng bao nhiêu kg?",en:"10000 kg of paddy at 20% moisture adjusted to a 14% standard is about how many kg?"},options:{vi:["9400 kg","9302 kg","8600 kg","9860 kg"],en:["9400 kg","9302 kg","8600 kg","9860 kg"]},answer:1,explain:{vi:"Khối lượng quy đổi = 10000 x 80 / 86 ≈ 9302 kg; trừ 1% mỗi độ ẩm cho kết quả sai 9400 kg.",en:"Adjusted weight = 10000 x 80 / 86 ≈ 9302 kg; deducting 1% per point gives the wrong 9400 kg."}},{q:{vi:"Theo Incoterms 2020, điều kiện nào người bán chịu chi phí đưa hàng tới nơi đến chỉ định, chưa dỡ hàng?",en:"Under Incoterms 2020, which rule has the seller bear the cost to the named destination, not unloaded?"},options:{vi:["EXW","FCA","FOB","DAP"],en:["EXW","FCA","FOB","DAP"]},answer:3,explain:{vi:"DAP: người bán giao hàng trên phương tiện tại nơi đến chỉ định, sẵn sàng để dỡ.",en:"DAP: the seller delivers on the arriving vehicle at the named place, ready for unloading."}},{q:{vi:"Hợp tác xã gửi tiền bồi dưỡng để bạn bỏ qua mẫu ẩm cao. Bạn làm gì?",en:"A cooperative offers you money to overlook a high-moisture sample. What do you do?"},options:{vi:["Từ chối, báo cáo và đo lại có chứng kiến","Nhận nhưng vẫn đo đúng","Nhận và chia cho đồng nghiệp","Bỏ qua lần này"],en:["Decline, report it and re-test with witnesses","Accept but still test correctly","Accept and share with colleagues","Let it go this time"]},answer:0,explain:{vi:"Nhận tiền từ nhà cung cấp là xung đột lợi ích, có thể là hành vi hối lộ; phải từ chối và báo cáo.",en:"Taking supplier money is a conflict of interest and may be bribery; decline and report it."}},{q:{vi:"Lợi ích chính của giá sàn trong hợp đồng liên kết với nông dân là gì?",en:"What is the main benefit of a floor price in a linkage contract with farmers?"},options:{vi:["Giúp công ty luôn mua rẻ","Không cần kiểm tra chất lượng","Bảo vệ thu nhập tối thiểu của nông dân khi giá thị trường giảm","Loại bỏ nghĩa vụ thuế"],en:["The company always buys cheap","No quality checks are needed","It protects farmers' minimum income when prices fall","It removes tax obligations"]},answer:2,explain:{vi:"Giá sàn chia sẻ rủi ro giá, giúp nông dân yên tâm đầu tư và giữ vùng nguyên liệu ổn định.",en:"A floor price shares price risk, encouraging farmers to invest and stabilising supply."}}]}},"KK-957":{scenario:{company:"Red River Snack Foods",supervisor:{name:"Lương Đức Thịnh",role:{vi:"Giám đốc Vận hành",en:"Operations Director"}},ref_code:"OEE-W45",title:{vi:"Gọi đúng tổn thất. Tính đúng OEE. Không đánh đổi an toàn.",en:"Name the loss. Compute OEE right. Never trade safety."},brief:{vi:"Bạn hoàn thiện báo cáo hiệu suất OEE-W45 cho dây chuyền đóng gói bánh quy ca 1. Ca dài 480 phút, nghỉ giữa ca có kế hoạch 30 phút; hỏng máy và chuyển đổi sản phẩm làm dừng 45 phút. Tốc độ lý tưởng 120 gói/phút; tổng sản lượng 43740 gói, trong đó 41553 gói đạt. Máy đóng gói kẹt nhiều lần dưới 2 phút và chạy chậm. Sửa phân loại tổn thất và chỉ số OEE (%), rồi lập báo cáo có căn cứ.",en:"You are finalising performance report OEE-W45 for the biscuit packing line, shift 1. The shift is 480 minutes with a planned 30-minute break; breakdowns and product changeovers stopped the line for 45 minutes. Ideal rate is 120 packs per minute; total output was 43740 packs, of which 41553 were good. The packer jammed many times for under 2 minutes and ran slow. Correct the loss category and the OEE (%), then write an evidence-based report."},reference_title:{vi:"Nhật ký ca & chuẩn tính OEE đã duyệt · OEE-W45",en:"Approved shift log & OEE standard · OEE-W45"},fields:[{id:"LOSS_CLASS",label:{vi:"Nhóm tổn thất của dừng ngắn & chạy chậm",en:"Loss category of minor stops & slow running"},initial:"AVAILABILITY",expected:"PERFORMANCE",choices:["AVAILABILITY","PERFORMANCE","QUALITY"],reference:"Bảng 6 tổn thất lớn (Six Big Losses)",hint:{vi:"Dừng ngắn và giảm tốc độ làm giảm hiệu suất; hỏng máy và chuyển đổi mới thuộc nhóm thời gian sẵn sàng.",en:"Minor stops and reduced speed lower performance; breakdowns and changeovers belong to availability."}},{id:"OEE_PCT",label:{vi:"OEE ca 1 (%)",en:"Shift 1 OEE (%)"},initial:"72.14",expected:"76.95",reference:"Nhật ký thời gian & sản lượng ca 1",ref_value:{vi:"Ca 480 phút; nghỉ kế hoạch 30; dừng 45; 120 gói/phút; tổng 43740; đạt 41553",en:"Shift 480 min; planned break 30; downtime 45; 120 packs/min; total 43740; good 41553"},hint:{vi:"Thời gian sản xuất kế hoạch phải trừ nghỉ có kế hoạch trước khi tính tỷ lệ sẵn sàng.",en:"Planned production time excludes the planned break before availability is calculated."}}],sop32:{vi:"OEE = A x P x Q; A = thời gian chạy / (ca - nghỉ có kế hoạch); P = tổng sản lượng / (thời gian chạy x tốc độ lý tưởng); Q = sản phẩm đạt / tổng sản lượng; ghi % làm tròn 2 chữ số.",en:"OEE = A x P x Q; A = run time / (shift - planned break); P = total output / (run time x ideal rate); Q = good output / total output; report % to 2 decimals."},context:{label:"MES / OEE-W45",metrics:[{label:{vi:"Thời gian ca",en:"Shift time"},value:"480 min"},{label:{vi:"Dừng không kế hoạch",en:"Unplanned downtime"},value:"45 min"},{label:{vi:"Sản lượng tổng / đạt",en:"Total / good output"},value:"43740 / 41553"}]},crisis:{vi:"Giám đốc nhà máy nhắn: “Máy dò kim loại báo lỗi liên tục, tắt nó đi cho chuyền chạy, đơn 20 tấn phải xuất tối nay. Máy quá nhạy thôi, lô trước có sao đâu.”",en:"The plant director messages you: “The metal detector keeps rejecting, switch it off so the line can run, the 20-tonne order ships tonight. It's just oversensitive, the last lot was fine.”"},options:{safe:{vi:"Không tắt máy dò kim loại vì đây là CCP; cách ly sản phẩm từ lần thử mẫu chuẩn đạt gần nhất, gọi bảo trì và QA kiểm tra, báo giám đốc vận hành, khách hàng về khả năng trễ và bố trí ca bù.",en:"Do not bypass the metal detector, it is a CCP; hold product since the last passing test piece check, call maintenance and QA, inform the operations director and customer of a possible delay and plan a catch-up shift."},shortcut:{vi:"Tắt máy dò kim loại để chạy kịp đơn hàng, ghi chú kiểm tra lại sau.",en:"Switch off the metal detector to make the order and note a check for later."},wait:{vi:"Dừng chuyền, chờ giám đốc nhà máy tự xử lý và không báo ai.",en:"Stop the line, wait for the plant director to sort it out and tell no one."}},questions:{vi:["Vì sao dừng ngắn thuộc nhóm PERFORMANCE và OEE ca 1 là 76.95%? Số liệu nào chứng minh?","Bạn cân bằng tiến độ đơn hàng 20 tấn với yêu cầu không bỏ qua CCP máy dò kim loại thế nào?"],en:["Why do minor stops count as PERFORMANCE and why is shift 1 OEE 76.95%? Which data proves it?","How do you balance the 20-tonne order deadline with the rule never to bypass the metal detector CCP?"]},hints:{vi:["Đặt nhật ký dừng máy cạnh bảng 6 tổn thất lớn và phân loại từng sự kiện.","Tính lần lượt A, P, Q từ thời gian sản xuất kế hoạch đã trừ nghỉ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không được vô hiệu hóa thiết bị kiểm soát CCP; mọi áp lực phải báo cáo."],en:["Place the stop log next to the Six Big Losses table and classify each event.","Calculate A, P and Q in turn from planned production time net of the break as in SOP 3.2.","Re-read SOP 4.2: CCP control devices are never disabled; any pressure must be escalated."]}},learning:{summary:{vi:"Quản lý sản xuất nhà máy chế biến thực phẩm lập kế hoạch và điều phối con người, máy móc, nguyên liệu để sản xuất đúng sản lượng, đúng chất lượng, an toàn và chi phí tối ưu. Nghề đòi hỏi thành thạo chỉ số vận hành như OEE, năng suất lao động, tiêu hao nguyên liệu, kết hợp với hệ thống an toàn thực phẩm, an toàn lao động và kỹ năng lãnh đạo đội ngũ theo ca.",en:"A food plant production manager plans and coordinates people, machines and materials to deliver the right volume at the right quality, safely and at optimal cost. The role requires mastery of operating metrics such as OEE, labour productivity and material usage, combined with food safety and occupational safety systems and the ability to lead shift teams."},responsibilities:{vi:["Lập kế hoạch sản xuất ngày, tuần theo đơn hàng, tồn kho và năng lực dây chuyền.","Điều phối nhân sự ca, bảo trì, kho và QA để dây chuyền chạy ổn định.","Theo dõi OEE, tiêu hao nguyên vật liệu, phế phẩm và triển khai cải tiến liên tục.","Bảo đảm tuân thủ HACCP, GMP, an toàn lao động và môi trường tại xưởng.","Báo cáo hiệu suất, chi phí và xử lý sự cố với ban giám đốc, khách hàng."],en:["Plan daily and weekly production from orders, stock and line capacity.","Coordinate shift staff, maintenance, warehouse and QA to keep lines stable.","Track OEE, material usage and scrap and drive continuous improvement.","Ensure HACCP, GMP, occupational safety and environmental compliance on the floor.","Report performance and cost and handle incidents with management and customers."]},competencies:[{name:{vi:"Lập kế hoạch & điều độ",en:"Planning & scheduling"},desc:{vi:"Cân đối đơn hàng, nguyên liệu, nhân lực và thời gian chuyển đổi để đạt kế hoạch.",en:"Balance orders, materials, labour and changeovers to hit the plan."}},{name:{vi:"Quản lý hiệu suất (OEE)",en:"Performance management (OEE)"},desc:{vi:"Đo đúng, phân loại đúng tổn thất và chọn ưu tiên cải tiến có tác động lớn nhất.",en:"Measure and classify losses correctly and prioritise the highest-impact improvements."}},{name:{vi:"Cải tiến tinh gọn",en:"Lean improvement"},desc:{vi:"Áp dụng 5S, SMED, Kaizen, giải quyết vấn đề tận gốc với nhóm sản xuất.",en:"Apply 5S, SMED and Kaizen and solve root causes with the production team."}},{name:{vi:"An toàn thực phẩm & lao động",en:"Food & workplace safety"},desc:{vi:"Không đánh đổi CCP, vệ sinh và an toàn người lao động để lấy sản lượng.",en:"Never trade CCPs, hygiene or worker safety for output."}},{name:{vi:"Lãnh đạo đội ngũ ca",en:"Shift team leadership"},desc:{vi:"Giao việc rõ, huấn luyện tại chỗ và xây dựng văn hóa báo cáo sự cố.",en:"Assign clearly, coach on the floor and build a culture of reporting issues."}}],knowledge:{vi:["OEE và 6 tổn thất lớn trong bảo trì năng suất toàn diện (TPM).","Sản xuất tinh gọn: 5S, SMED, Kaizen, quản lý trực quan.","ISO 22000, HACCP, GMP và vai trò của các CCP như máy dò kim loại, nhiệt độ nấu.","ISO 45001 về hệ thống quản lý an toàn, sức khỏe nghề nghiệp.","Hoạch định nhu cầu vật tư (MRP) và lập kế hoạch bán hàng & vận hành (S&OP)."],en:["OEE and the Six Big Losses in total productive maintenance (TPM).","Lean manufacturing: 5S, SMED, Kaizen and visual management.","ISO 22000, HACCP, GMP and the role of CCPs such as metal detection and cooking temperature.","ISO 45001 on occupational health and safety management systems.","Material requirements planning (MRP) and sales and operations planning (S&OP)."]},tools:["Hệ thống điều hành sản xuất (MES)","Phần mềm ERP","Bảng điều khiển OEE thời gian thực","Bảng quản lý trực quan tại chuyền","Máy dò kim loại & mẫu thử chuẩn"],kpis:{vi:["OEE từng dây chuyền so với mục tiêu.","Tỷ lệ đơn hàng giao đúng hạn, đủ số lượng.","Tiêu hao nguyên liệu và tỷ lệ phế phẩm.","Số sự cố an toàn thực phẩm và tai nạn lao động (mục tiêu bằng 0)."],en:["OEE per line versus target.","On-time, in-full delivery rate.","Material usage and scrap rate.","Food safety incidents and workplace accidents (target zero)."]},day:[{time:"07:00",vi:"Họp giao ca, xem OEE ca đêm, sự cố và kế hoạch trong ngày.",en:"Shift handover meeting reviewing night-shift OEE, incidents and today's plan."},{time:"08:00",vi:"Đi kiểm tra hiện trường (gemba), xác nhận thử mẫu chuẩn máy dò kim loại.",en:"Gemba walk and confirmation of metal detector test piece checks."},{time:"10:00",vi:"Điều chỉnh kế hoạch khi nguyên liệu về trễ, sắp xếp lại thứ tự chạy.",en:"Adjust the plan for late materials and resequence production runs."},{time:"14:00",vi:"Họp cải tiến giảm thời gian chuyển đổi sản phẩm theo SMED.",en:"Improvement meeting to cut changeover time using SMED."},{time:"16:30",vi:"Báo cáo ngày, chuẩn bị kế hoạch và nhân sự cho ca tối.",en:"Daily report and preparation of the plan and staffing for the evening shift."}],mistakes:{vi:["Tính OEE trên toàn bộ thời gian ca, không trừ nghỉ có kế hoạch, làm sai chuẩn so sánh.","Xếp dừng ngắn vào nhóm sẵn sàng, che mất vấn đề tốc độ của máy đóng gói.","Bỏ qua cảnh báo CCP để chạy kịp sản lượng."],en:["Calculating OEE on the full shift without removing planned breaks, distorting comparisons.","Classing minor stops as availability and hiding the packer's speed problem.","Ignoring a CCP alarm to make volume."]},career:[{vi:"Tổ trưởng sản xuất",en:"Production team leader"},{vi:"Trưởng ca sản xuất",en:"Shift production supervisor"},{vi:"Quản lý sản xuất nhà máy",en:"Plant production manager"},{vi:"Giám đốc nhà máy",en:"Plant director"}],glossary:[{term:"OEE",vi:"Hiệu suất thiết bị tổng thể = sẵn sàng x hiệu suất x chất lượng.",en:"Overall equipment effectiveness = availability x performance x quality."},{term:"Six Big Losses",vi:"6 tổn thất lớn: hỏng máy, chuyển đổi, dừng ngắn, giảm tốc, phế phẩm khởi động, phế phẩm sản xuất.",en:"Breakdowns, changeovers, minor stops, reduced speed, startup rejects and production rejects."},{term:"SMED",vi:"Phương pháp chuyển đổi khuôn, sản phẩm trong vài phút bằng cách tách việc trong và ngoài máy.",en:"Single-minute exchange of die: cutting changeovers by separating internal and external tasks."},{term:"Gemba",vi:"Hiện trường nơi giá trị được tạo ra; quản lý đi gemba để thấy vấn đề thật.",en:"The place where value is created; managers walk the gemba to see real problems."},{term:"CCP",vi:"Điểm kiểm soát tới hạn trong HACCP, ví dụ máy dò kim loại hoặc nhiệt độ nấu.",en:"Critical control point in HACCP, such as metal detection or cooking temperature."}],quiz:[{q:{vi:"Sẵn sàng 0.9, hiệu suất 0.8, chất lượng 0.95. OEE bằng bao nhiêu?",en:"Availability 0.9, performance 0.8, quality 0.95. What is the OEE?"},options:{vi:["90%","68.4%","85%","72%"],en:["90%","68.4%","85%","72%"]},answer:1,explain:{vi:"OEE = 0.9 x 0.8 x 0.95 = 0.684, tức 68.4%.",en:"OEE = 0.9 x 0.8 x 0.95 = 0.684, or 68.4%."}},{q:{vi:"Thời gian chuyển đổi sản phẩm thuộc nhóm tổn thất nào trong OEE?",en:"Which OEE loss category does product changeover time belong to?"},options:{vi:["Chất lượng","Hiệu suất","Sẵn sàng (Availability)","Không tính vào OEE"],en:["Quality","Performance","Availability","Not counted in OEE"]},answer:2,explain:{vi:"Chuyển đổi và hỏng máy làm dừng chuyền có thời lượng đáng kể nên thuộc nhóm sẵn sàng.",en:"Changeovers and breakdowns stop the line for significant time, so they reduce availability."}},{q:{vi:"Máy dò kim loại báo lỗi khi đang chạy đơn gấp. Bạn làm gì?",en:"The metal detector alarms during an urgent order. What do you do?"},options:{vi:["Tắt máy dò","Chạy tiếp và ghi chú","Giảm độ nhạy máy","Dừng, cách ly sản phẩm từ lần thử đạt gần nhất, gọi QA và bảo trì"],en:["Switch the detector off","Keep running and add a note","Lower the sensitivity","Stop, hold product since the last passing check and call QA and maintenance"]},answer:3,explain:{vi:"Máy dò kim loại là CCP; vô hiệu hóa nó có thể đưa dị vật kim loại tới người tiêu dùng.",en:"The metal detector is a CCP; disabling it can let metal fragments reach consumers."}},{q:{vi:"Mục tiêu của SMED là gì?",en:"What is the goal of SMED?"},options:{vi:["Giảm thời gian chuyển đổi sản phẩm","Tăng số công nhân","Kéo dài ca làm việc","Thay thế bảo trì định kỳ"],en:["Cut product changeover time","Add more workers","Extend the shift","Replace planned maintenance"]},answer:0,explain:{vi:"SMED tách công việc làm được khi máy chạy ra ngoài để rút ngắn thời gian dừng chuyển đổi.",en:"SMED moves tasks that can be done while running outside the stop to shorten changeovers."}}]}},"KK-958":{scenario:{company:"Mekong Orchard Export",supervisor:{name:"Mạc Quang Thiện",role:{vi:"Trưởng phòng Xuất khẩu",en:"Export Manager"}},ref_code:"KD-5523",title:{vi:"Đúng mã vùng trồng. Đúng khối lượng. Giữ thị trường cho cả vùng.",en:"Right orchard code. Right weight. Keep the market open."},brief:{vi:"Bạn chuẩn bị hồ sơ đăng ký kiểm dịch KD-5523 cho một container thanh long tươi xuất khẩu. Phiếu đóng gói: 1560 thùng, mỗi thùng 5 kg tịnh; trong đó 312 thùng thu từ vườn có mã số vùng trồng đã bị tạm dừng sau lần phát hiện sinh vật gây hại. Phòng xuất khẩu đã đối chiếu danh sách mã số vùng trồng còn hiệu lực. Sửa mã số vùng trồng và khối lượng tịnh khai báo, rồi lập báo cáo có căn cứ.",en:"You are preparing phytosanitary inspection request KD-5523 for one container of fresh dragon fruit for export. Packing list: 1560 cartons, 5 kg net each; 312 of them came from an orchard whose production unit code was suspended after a pest interception. The export team has checked the list of valid production unit codes. Correct the production unit code and the declared net weight, then write an evidence-based report."},reference_title:{vi:"Danh sách mã số vùng trồng hiệu lực & phiếu đóng gói · KD-5523",en:"Valid production unit code list & packing list · KD-5523"},fields:[{id:"PUC_CODE",label:{vi:"Mã số vùng trồng khai báo",en:"Declared production unit code"},initial:"PUC-LA-0142",expected:"PUC-LA-0417",choices:["PUC-LA-0142","PUC-LA-0417","PUC-TG-0088"],reference:"Danh sách mã số vùng trồng còn hiệu lực",hint:{vi:"Chỉ khai mã số đang còn hiệu lực trong danh sách đã phê duyệt; mã của vườn bị tạm dừng không được sử dụng.",en:"Declare only a code that is valid on the approved list; a suspended orchard's code cannot be used."}},{id:"NET_KG",label:{vi:"Khối lượng tịnh khai báo (kg)",en:"Declared net weight (kg)"},initial:"7800",expected:"6240",reference:"Phiếu đóng gói theo vườn",ref_value:{vi:"1560 thùng x 5 kg tịnh; 312 thùng từ vườn có mã bị tạm dừng",en:"1560 cartons x 5 kg net; 312 cartons from the suspended orchard"},hint:{vi:"Thùng từ vườn có mã bị tạm dừng phải tách khỏi lô xuất, không được tính vào khối lượng khai báo.",en:"Cartons from the suspended orchard must be removed from the export lot and excluded from the declared weight."}}],sop32:{vi:"Chỉ khai các thùng từ vùng trồng có mã số còn hiệu lực; khối lượng tịnh = số thùng hợp lệ x khối lượng tịnh mỗi thùng; thùng không hợp lệ tách lô và lập biên bản.",en:"Declare only cartons from production units with a valid code; net weight = valid cartons x net weight per carton; invalid cartons are separated and recorded."},context:{label:"HỒ SƠ KIỂM DỊCH NHÁP / KD-5523",metrics:[{label:{vi:"Tổng số thùng",en:"Total cartons"},value:"1560"},{label:{vi:"Khối lượng tịnh mỗi thùng",en:"Net weight per carton"},value:"5 kg"},{label:{vi:"Thùng từ mã bị tạm dừng",en:"Cartons from suspended code"},value:"312"}]},crisis:{vi:"Giám đốc kinh doanh nhắn: “Cứ để 312 thùng vườn B chung container, dán nhãn mã PUC-LA-0417 cho đủ hàng. Đối tác đang chờ, lần trước có ai mở kiểm tra từng thùng đâu.”",en:"The sales director messages you: “Keep orchard B's 312 cartons in the container and label them PUC-LA-0417 to fill the order. The buyer is waiting and nobody opened every carton last time.”"},options:{safe:{vi:"Từ chối dán nhãn sai mã số vùng trồng; tách 312 thùng để tiêu thụ nội địa, khai đúng 6240 kg, báo trưởng phòng xuất khẩu, thông báo đối tác và đề xuất bổ sung hàng từ vườn có mã hợp lệ.",en:"Refuse to mislabel the production unit code; separate the 312 cartons for the domestic market, declare 6240 kg, inform the export manager, notify the buyer and propose topping up from a valid orchard."},shortcut:{vi:"Dán nhãn mã PUC-LA-0417 cho cả 1560 thùng để giao đủ container đúng hẹn.",en:"Label all 1560 cartons PUC-LA-0417 to ship a full container on time."},wait:{vi:"Chưa nộp hồ sơ, chờ giám đốc kinh doanh tự quyết định việc ghép hàng.",en:"Hold the filing and wait for the sales director to decide on mixing the lots."}},questions:{vi:["Vì sao khai mã PUC-LA-0417 và khối lượng tịnh 6240 kg? Chứng từ nào chứng minh?","Nêu rủi ro cho doanh nghiệp và cả vùng trồng nếu dán sai mã số, và cách bạn xử lý với đối tác nhập khẩu."],en:["Why did you declare PUC-LA-0417 and a net weight of 6240 kg? Which documents prove it?","Describe the risks to the company and the whole growing area from mislabelling the code, and how you handle the importer."]},hints:{vi:["Đối chiếu từng mã trên phiếu đóng gói với danh sách mã số vùng trồng còn hiệu lực.","Trừ số thùng của vườn bị tạm dừng trước khi nhân khối lượng tịnh mỗi thùng theo SOP mục 3.2.","Đọc lại SOP mục 4.2: gian lận mã số vùng trồng có thể khiến cả thị trường bị đình chỉ; phải báo cáo."],en:["Check each code on the packing list against the list of valid production unit codes.","Subtract the suspended orchard's cartons before multiplying by net weight per carton as in SOP 3.2.","Re-read SOP 4.2: code fraud can get the whole market suspended; it must be escalated."]}},learning:{summary:{vi:"Chuyên viên xuất khẩu nông sản và kiểm dịch chuẩn bị, kiểm soát hồ sơ để rau quả, nông sản đáp ứng yêu cầu kiểm dịch thực vật, an toàn thực phẩm và truy xuất của nước nhập khẩu: mã số vùng trồng, cơ sở đóng gói, xử lý kiểm dịch, chứng thư kiểm dịch và dư lượng thuốc bảo vệ thực vật. Nghề giữ cửa thị trường cho cả doanh nghiệp và vùng trồng nên đòi hỏi chính xác, hiểu quy định quốc tế và trung thực tuyệt đối.",en:"An agri-food export and phytosanitary officer prepares and controls the files that let fruit and produce meet the importing country's plant health, food safety and traceability requirements: production unit codes, packing house codes, quarantine treatments, phytosanitary certificates and pesticide residues. The role keeps markets open for the company and the whole growing area, so it demands precision, knowledge of international rules and complete honesty."},responsibilities:{vi:["Theo dõi yêu cầu kiểm dịch và an toàn thực phẩm của từng thị trường nhập khẩu.","Quản lý mã số vùng trồng, cơ sở đóng gói và hồ sơ truy xuất của từng lô hàng.","Đăng ký kiểm dịch, phối hợp xử lý kiểm dịch (chiếu xạ, hơi nước nóng, xử lý lạnh) khi được yêu cầu.","Kiểm tra nội bộ lô hàng: sinh vật gây hại, quy cách đóng gói, nhãn mác, vật liệu gỗ.","Xử lý cảnh báo, vi phạm từ nước nhập khẩu và lập kế hoạch khắc phục."],en:["Track the plant health and food safety requirements of each importing market.","Manage production unit codes, packing house codes and traceability files for every lot.","Request inspections and arrange quarantine treatments (irradiation, vapour heat, cold) when required.","Pre-inspect lots for pests, packing standards, labels and wood packaging.","Handle notifications and violations from importing countries and plan corrective actions."]},competencies:[{name:{vi:"Hiểu quy định kiểm dịch quốc tế",en:"International phytosanitary rules"},desc:{vi:"Nắm tiêu chuẩn IPPC, hiệp định SPS và yêu cầu riêng của từng nước nhập khẩu.",en:"Know IPPC standards, the SPS Agreement and each importer's specific requirements."}},{name:{vi:"Quản lý hồ sơ & truy xuất",en:"Documentation & traceability"},desc:{vi:"Liên kết từng thùng hàng với vườn, cơ sở đóng gói và nhật ký canh tác.",en:"Link every carton to its orchard, packing house and crop records."}},{name:{vi:"Kiểm soát chất lượng lô hàng",en:"Lot quality control"},desc:{vi:"Kiểm tra sinh vật gây hại, dư lượng, quy cách và nhãn trước khi đăng ký kiểm dịch.",en:"Check pests, residues, packing and labels before requesting inspection."}},{name:{vi:"Phối hợp chuỗi cung ứng",en:"Supply chain coordination"},desc:{vi:"Làm việc với vườn, cơ sở đóng gói, đơn vị xử lý, hãng tàu và cơ quan kiểm dịch.",en:"Work with orchards, packing houses, treatment facilities, carriers and the quarantine authority."}},{name:{vi:"Liêm chính thương mại",en:"Trade integrity"},desc:{vi:"Từ chối gian lận mã số, nhãn mác dù chịu áp lực doanh số và báo cáo kịp thời.",en:"Refuse code and label fraud under sales pressure and escalate promptly."}}],knowledge:{vi:["Công ước Bảo vệ thực vật quốc tế (IPPC) và tiêu chuẩn ISPM, gồm ISPM 12 về chứng thư kiểm dịch, ISPM 15 về vật liệu đóng gói bằng gỗ.","Hiệp định về các biện pháp vệ sinh và kiểm dịch động thực vật (SPS) của WTO.","Luật Bảo vệ và kiểm dịch thực vật số 41/2013/QH13 và quy định về mã số vùng trồng, cơ sở đóng gói.","Giới hạn dư lượng tối đa (MRL) của Codex và của từng thị trường nhập khẩu.","Các phương pháp xử lý kiểm dịch: chiếu xạ, hơi nước nóng, xử lý lạnh, xông hơi."],en:["International Plant Protection Convention (IPPC) and ISPM standards, including ISPM 12 on phytosanitary certificates and ISPM 15 on wood packaging.","The WTO Agreement on Sanitary and Phytosanitary Measures (SPS).","Law on Plant Protection and Quarantine No. 41/2013/QH13 and rules on production unit and packing house codes.","Codex and importing-country maximum residue limits (MRL).","Quarantine treatments: irradiation, vapour heat, cold treatment and fumigation."]},tools:["Cổng một cửa quốc gia (khai báo điện tử)","Cơ sở dữ liệu mã số vùng trồng","Kính lúp & bàn soi sinh vật gây hại","Phần mềm truy xuất lô hàng","Bảng tính phiếu đóng gói"],kpis:{vi:["Số lô bị nước nhập khẩu cảnh báo hoặc trả về (mục tiêu bằng 0).","Tỷ lệ hồ sơ kiểm dịch đúng ngay lần đầu.","Thời gian từ đóng gói đến khi có chứng thư kiểm dịch.","Tỷ lệ lô hàng truy xuất đầy đủ đến vườn trồng."],en:["Lots notified or rejected by importing countries (target zero).","Right-first-time phytosanitary filing rate.","Time from packing to phytosanitary certificate.","Share of lots fully traceable to the orchard."]},day:[{time:"07:30",vi:"Kiểm tra cập nhật danh sách mã số vùng trồng và cảnh báo từ thị trường.",en:"Check updates to the production unit code list and market notifications."},{time:"09:00",vi:"Có mặt cơ sở đóng gói, kiểm tra ngẫu nhiên thùng hàng, nhãn và pallet gỗ.",en:"At the packing house, spot-check cartons, labels and wooden pallets."},{time:"11:00",vi:"Đăng ký kiểm dịch và đặt lịch xử lý kiểm dịch cho lô hàng.",en:"File the inspection request and book the quarantine treatment slot."},{time:"14:00",vi:"Đối chiếu phiếu đóng gói theo từng vườn với mã số còn hiệu lực.",en:"Match the packing list by orchard against valid codes."},{time:"16:30",vi:"Cập nhật hồ sơ truy xuất và gửi bộ chứng từ cho khách hàng nhập khẩu.",en:"Update traceability files and send the document set to the importer."}],mistakes:{vi:["Dùng mã số vùng trồng của mùa trước mà không kiểm tra tình trạng hiệu lực.","Ghép hàng từ vườn không có mã hợp lệ vào lô xuất cho đủ container.","Dùng pallet gỗ chưa xử lý, không có dấu ISPM 15."],en:["Reusing last season's production unit code without checking it is still valid.","Mixing produce from orchards without a valid code into the export lot to fill a container.","Using untreated wooden pallets without the ISPM 15 mark."]},career:[{vi:"Nhân viên chứng từ xuất khẩu nông sản",en:"Agri-food export documentation assistant"},{vi:"Chuyên viên xuất khẩu & kiểm dịch",en:"Export & phytosanitary officer"},{vi:"Trưởng phòng xuất khẩu",en:"Export manager"},{vi:"Giám đốc phát triển thị trường nông sản",en:"Agri-food market development director"}],glossary:[{term:"PUC",vi:"Mã số vùng trồng: mã định danh vùng sản xuất được cấp để truy xuất và giám sát sinh vật gây hại.",en:"Production unit code identifying a growing area for traceability and pest surveillance."},{term:"Phytosanitary certificate",vi:"Chứng thư kiểm dịch thực vật do cơ quan có thẩm quyền nước xuất khẩu cấp cho lô hàng.",en:"Plant health certificate issued for a consignment by the exporting country's authority."},{term:"ISPM 15",vi:"Tiêu chuẩn quốc tế về xử lý và đánh dấu vật liệu đóng gói bằng gỗ trong thương mại.",en:"International standard for treating and marking wood packaging material in trade."},{term:"SPS",vi:"Hiệp định WTO về biện pháp vệ sinh an toàn thực phẩm và kiểm dịch động thực vật.",en:"WTO agreement on sanitary and phytosanitary measures."},{term:"MRL",vi:"Giới hạn dư lượng tối đa của thuốc bảo vệ thực vật được phép trong nông sản.",en:"Maximum residue limit of a pesticide permitted in produce."}],quiz:[{q:{vi:"ISPM 15 quy định về vấn đề gì?",en:"What does ISPM 15 cover?"},options:{vi:["Dư lượng thuốc trên quả","Xử lý và đánh dấu vật liệu đóng gói bằng gỗ","Nhãn dinh dưỡng","Quy cách thùng carton"],en:["Pesticide residues on fruit","Treatment and marking of wood packaging","Nutrition labelling","Carton specifications"]},answer:1,explain:{vi:"ISPM 15 yêu cầu vật liệu gỗ đóng gói được xử lý nhiệt hoặc xông hơi và đóng dấu theo mẫu quốc tế.",en:"ISPM 15 requires wood packaging to be heat-treated or fumigated and marked with the international mark."}},{q:{vi:"Lô 2000 thùng x 4 kg tịnh, trong đó 250 thùng từ vườn có mã bị tạm dừng. Khối lượng tịnh được khai là bao nhiêu?",en:"A lot of 2000 cartons x 4 kg net includes 250 cartons from a suspended orchard. What net weight may be declared?"},options:{vi:["8000 kg","1000 kg","7000 kg","7750 kg"],en:["8000 kg","1000 kg","7000 kg","7750 kg"]},answer:2,explain:{vi:"Số thùng hợp lệ = 2000 - 250 = 1750; khối lượng tịnh = 1750 x 4 = 7000 kg.",en:"Valid cartons = 2000 - 250 = 1750; net weight = 1750 x 4 = 7000 kg."}},{q:{vi:"Kinh doanh muốn dán mã vùng trồng hợp lệ lên hàng từ vườn bị tạm dừng. Bạn làm gì?",en:"Sales wants to put a valid code on produce from a suspended orchard. What do you do?"},options:{vi:["Đồng ý vì cùng tỉnh","Dán mã trên một phần thùng","Hỏi đối tác có chấp nhận không","Từ chối, tách lô, báo trưởng phòng và khai đúng"],en:["Agree since it is the same province","Label only some cartons","Ask the buyer if they mind","Refuse, separate the lot, inform the manager and declare correctly"]},answer:3,explain:{vi:"Gian lận mã số vùng trồng có thể khiến nước nhập khẩu đình chỉ cả vùng hoặc cả ngành hàng.",en:"Code fraud can lead the importing country to suspend the whole area or product sector."}},{q:{vi:"Mục đích chính của mã số vùng trồng là gì?",en:"What is the main purpose of a production unit code?"},options:{vi:["Truy xuất nguồn gốc và giám sát sinh vật gây hại tới từng vùng sản xuất","Tính thuế xuất khẩu","Quảng bá thương hiệu","Xác định giá bán"],en:["Trace origin and monitor pests down to each growing area","Calculate export tax","Promote a brand","Set the selling price"]},answer:0,explain:{vi:"Mã số vùng trồng giúp cơ quan kiểm dịch hai nước truy ngược lô hàng và khoanh vùng khi phát hiện sinh vật gây hại.",en:"The code lets both countries' authorities trace a lot back and contain problems when pests are found."}}]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(13)})(window.KKR);
